#include <boost/asio.hpp>
#include <lrucache11.hpp>
#include <chrono>
#include <string>
#include <iostream>

namespace asio = boost::asio;
using asio::ip::tcp;
using Cache = LRU11::Cache<std::string, std::string>;

class HttpClient {
public:
    HttpClient(asio::io_service& ioService) : resolver_(ioService), socket_(ioService){}

    void fetch(const std::string &server, const std::string &path) {
        // Fetch HTTP headers using asynchronous name resolution.
        tcp::resolver::query query(server, "http");
        resolver_.async_resolve(query, [this](boost::system::error_code ec, tcp::resolver::iterator it){
            if(!ec) {
                // Connect to the server.
                socket_.async_connect(*it, [this](boost::system::error_code ec){
                    if(!ec) {
                        // Send the HTTP request.
                        asio::write(socket_, asio::buffer("GET / HTTP 1.0\r\nHost: " + host_ + "\r\nAccept: */*\r\nConnection: close\r\n\r\n"));

                        // Read the response, store to cache and print it out.
                        asio::streambuf buffer;
                        std::ostringstream ss;
                        while(asio::read(socket_, buffer, boost::asio::transfer_at_least(1), ec)) {
                            ss << &buffer;
                        }

                        // Store in cache.
                        cache_.insertAbsent("header", ss.str());
                        std::cout << "Header: " << ss.str() << std::endl;
                    } else {
                        std::cerr << "Error connecting to server: " << ec.message() << std::endl;
                    }
                });
            } else {
                std::cerr << "Error resolving host name: " << ec.message() << std::endl;
            }
        });
    }
private:
    Cache cache_;
    tcp::resolver resolver_;
    tcp::socket socket_;
};
```

