```python
import os
import hashlib
import requests
from retrying import retry
from concurrent.futures import ThreadPoolExecutor

class DistributedFileProcessor:
    def __init__(self, api_url, auth_token):
        self.api_url = api_url
        self.auth_token = auth_token

    @retry(wait_exponential_multiplier=1000, wait_exponential_max=10000)
    def send_hash(self, hash):
        headers = {'Authorization': 'Bearer ' + self.auth_token}
        response = requests.post(self.api_url, json={'hash': hash}, headers=headers)
        if response.status_code != 200:
            raise Exception('API request failed with status code {}'.format(response.status_code))

    @retry(wait_exponential_multiplier=1000, wait_exponential_max=10000)
    def read_file(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                buffer = f.read(8192)
                while len(buffer):
                    yield buffer
                    buffer = f.read(8192)
        except Exception as e:
            raise e

    def hash_file(self, file_path):
        try:
            hasher = hashlib.sha256()
            for buf in self.read_file(file_path):
                hasher.update(buf)
            return hasher.hexdigest()
        except Exception as e:
            print('Error while processing file {}: {}'.format(file_path, str(e)))

    def process_files(self, files):
        with ThreadPoolExecutor(max_workers=5) as executor:
            for file in files:
                future = executor.submit(self.hash_file, file)
                try:
                    hash = future.result()
                    self.send_hash(hash)
                except Exception as e:
                    print('Error while processing file {}: {}'.format(file, str(e)))
``` 

Please note that this is a simplified version of what your module might look like and there are many other factors to consider for a production-level solution. This includes error handling for the thread pool executor, API rate limiting, more sophisticated file chunking strategies, potential storage solutions other than REST APIs, logging strategies, and monitoring tools. 

