["Here's an example of how you might implement a streaming data source integration in JavaScript. For simplicity, I am using NodeJS style callbacks for error handling:

```javascript
const fetch = require('node-fetch');

class DataSource {
  constructor(url) {
    this.url = url;
    this.cache = {};
    this.isPaused = false;
    this.intervalId = null;
  }

  start() {
    if (this.intervalId !== null) return; // Already started

    this._fetchData();
    this.intervalId = setInterval(() => {
      if (!this.isPaused) {
        this._fetchData();
      }
    }, 1000); // Adjust as needed
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
  }

  stop() {
    clearInterval(this.intervalId);
    this.intervalId = null;
  }

  async _fetchData() {
    try {
      const response = await fetch(this.url);
      const data = await response.json();
      if (response.ok) {
        this._validateAndStoreMetadata(data);
      } else {
