['Here's a rough skeleton for your Rust application that integrates with a C library using `std::process` to call the C function for loading resource bundles from a specified file path. However, keep in mind this is just an example and may need further modification based on specific requirements and constraints:

```rust
use std::{fs::File, io::Write, process::Command, time::Instant};
use mem::size_of_val;
use std::sync::Arc;
use crossbeam_channel::unbounded;

static LOGGER: Arc<Sender<LogMessage>> = Arc::new(unbounded());

#[derive(Debug)]
pub struct LogMessage {
    time: Instant,
    msg: String,
}

impl LogMessage {
    fn new(msg: &str) -> Self {
        Self {
            time: Instant::now(),
            msg: msg.to_string(),
        }
    }
}

pub async fn log_message(sender: Sender<LogMessage>, message: LogMessage) {
    let _ = sender.send(message);
}

fn c_function() -> Result<i32, String> {
    // This assumes that the C library has been linked and is in your system PATH
    match Command::new("load_resource").arg("file_path").output() {
        Ok(output) => match output.status.success() {
            true => match String::from_utf8(output.stdout) {
                Ok(count) => match count.trim().parse::<i32>() {
                    Ok(number) => Ok(number),
                    Err(_) => Err("Failed to parse output from C library".to_string()),
                },
                _ => Err("Failed to convert stdout to UTF-8 string".to_string()),
            },
            false => Err(format![Output: {}", String::from_utf8(output.stderr).unwrap()]),
        },
        Err(e) => Err(format![Error executing C library: {}", e],
    }
}

#[tokio::main]
async fn main() -> std::io::Result<()> {
    let start_time = Instant::now();
    match c_function() {
        Ok(number) => {
            printlnformat![The resource bundle contains {} items", number];
            log_message(LOGGER.clone(), LogMessage::new(&format![Loaded the bundle in {}", start_time.elapsed().as_secs())).unwrap();
            Ok(())
        }
        Err(e) => {
            printlnformat![Failed to load resource bundle: {}", e];
            log_message(LOGGER.clone(), LogMessage::new(&format![Error loading the bundle in {}", start_time.elapsed().as_secs())).unwrap();
            Err(std::io::Error::new(std::io::ErrorKind::Other, "Failed to load resource bundle"))
        }
    }
}
```
This example only includes a basic logging system using async channels. For complete feature set like dynamic configuration of resource paths, performance metrics reporting, robust error handling etc., you would need additional code and probably use crates that provide these features (like `config` for configuration management, `metrics` for metrics collection, `failure` or `anyhow` for error handling).
']

