```cpp
#include <vector>
#include <memory>

struct Point {
    double x, y, z;
};

class Octant {
public:
    Octant(const std::shared_ptr<Octant>& parent) : parent_(parent) {}
    ~Octant() = default;

    void addPoint(const Point &p) { points_.push_back(p); }
    const std::vector<Point>& getPoints() const { return points_; }

private:
    std::weak_ptr<Octant> parent_;
    std::vector<std::shared_ptr<Octant>> children_;
    std::vector<Point> points_;
};

class Octree {
public:
    explicit Octree(int capacity) : root_(std::make_shared<Octant>(nullptr)), capacity_(capacity) {}
    ~Octree() = default;

    void addPoint(const Point &p, const std::shared_ptr<Octant>& octant) {
        if (octant->getPoints().size() < capacity_) {
            octant->addPoint(p);
        } else {
            splitAndAddPoint(p, octant);
        }
    }

private:
    void splitAndAddPoint(const Point &p, const std::shared_ptr<Octant>& octant) {
        // Split the parent Octant into 8 sub-Octants
        for (int i = 0; i < 8; ++i) {
            octant->getChildren().push_back(std::make_shared<Octant>(octant));
        }

        // Distribute points from parent to children
        for (const auto& point : octant->getPoints()) {
            for (int i = 0; i < 8; ++i) {
                addPointToChild(point, i);  // Add point to one of the child Octants
            }
        }

        // Add new point to children
        addPointToCorrectChild(p, octant);
    }

    std::shared_ptr<Octant> root_;
    int capacity_;  // Max points in an Octant before splitting
};
```

This is just a basic scaffold and does not handle many of the requirements you've outlined. It also lacks any sort of error handling, database interaction or performance enhancements which are crucial for real-world use cases.
