['Here is a simple implementation for your request using modern C++ features such as smart pointers, std::future, std::async etc. It's important to note that dynamic library loading, including function invocation, isn't thread-safe in itself; we need to make sure threads synchronize access to our libraries:

```cpp
#include <dlfcn.h>
#include <iostream>
#include <memory>
#include <mutex>
#include <vector>
#include <future>
#include <algorithm>

typedef void(*Func)(); // Function type: no arguments, no return value

class Library {
public:
    Library(const std::string& path): handle_(nullptr), func_(nullptr) {
        handle_ = dlopen(path.c_str(), RTLD_LAZY);
        if (!handle_) {
            throw std::runtime_error("Failed to open library: " + std::string(dlerror()));
        }
    }

    ~Library() {
        if (handle_) {
            dlclose(handle_);
        }
    }

    void LoadFunction(const std::string& name) {
        auto sym = dlsym(handle_, name.c_str());
        func_ = reinterpret_cast<Func>(sym);
        if (!func_) {
            throw std::runtime_error("Failed to load function: " + std::string(dlerror()));
        }
    }

    void InvokeFunction() const {
        if (func_) {
            func_();
        } else {
            throw std::logic_error("No function loaded");
        }
    }
private:
    void* handle_;
    Func func_;
};

class LibraryManager {
public:
    void LoadLibrary(const std::string& path) {
        std::lock_guard<std::mutex> lock(mtx_);
        libraries_.emplace_back(new Library(path));
    }

    void InvokeFunctionFromAllLibraries() {
        std::vector<std::future<void>> futures;

        for (auto& lib : libraries_) {
            futures.push_back(std::async([&lib](){ 
                std::lock_guard<std::mutex> lock(mtx_); 
                lib->InvokeFunction(); 
            }));
        }

        // Wait for all threads to finish
        std::for_each(futures.begin(), futures.end(), [](std::future<void> &ftr) {
            ftr.wait();
        });
    }
private:
    std::mutex mtx_;
    std::vector<std::unique_ptr<Library>> libraries_;
};
```
This code is a simplification of what you are asking for, and lacks many important aspects like error handling, logging etc. You should definitely add these as needed in the real-world applications. Also, keep in mind that managing resources manually with raw pointers can be error prone and it's better to use RAII classes (like std::unique_ptr) in this case.
']

