// Define the token schema as a struct
typedef struct {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
} Token;

Token tokens[1024]; // Assume we can only handle 1024 concurrent tokens at once. For production, this could be a linked list or dynamic array.
int numTokens = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void validateToken(char* tokenStr) {
    json_error_t error;
    Token token;

    // Parse the JSON string
    json_t *root = json_loads(tokenStr, 0, &error);
    if(!root) {
        printf("Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return;
    }

    // Extract the fields from the JSON object
    json_t *access_token = json_object_get(root, "access_token");
    if(!json_is_string(access_token)) {
        printf("Invalid access token\n");
        return;
    }
    token.access_token = (char*)json_string_value(access_token);

    // Do the same for expires_in, token_type and refresh_token

    pthread_mutex_lock(&mutex);
    tokens[numTokens++] = token;
    pthread_mutex_unlock(&mutex);
}

void* handleRequest(void *arg) {
    char* requestJson = (char*)arg;

    // Extract the access_token field from the incoming JSON. You may need to validate this is an array of tokens.
    json_t *root, *access_tokens;
    json_error_t error;

    root = json_loads(requestJson, 0, &error);
    if(!json_is_array(root)) {
        printf("Error: request is not an array of tokens\n");
        return NULL;
    }

    access_tokens = json_object_get(root, "access_token"); // replace this with the actual field name in your JSON

    for (int i = 0; i < json_array_size(access_tokens); i++) {
        char* tokenStr = (char*)json_string_value(json_array_get(access_tokens, i));

        validateToken(tokenStr); // Assume this function validates the token against OAuth2 schema. 
    }

    return NULL;
}

int main() {
    curl_global_init(CURL_GLOBAL_ALL); // Initialize libcurl globally, which will be used to make requests to OAuth2 API.

    while (1) {
        char* requestJson = getRequest(); 

        pthread_t thread;
        pthread_create(&thread, NULL, handleRequest, requestJson); // Create a new thread for each incoming JSON string
    }
}
