#include <openssl/evp.h>
#include <glib.h>  /* Glib Graph Library */
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>

#define MAX_VERTEXES 100
#define MAX_EDGES 1000
#define MAX_BUFFER 256

/* Cryptographic Algorithms */
typedef enum {AES, CAMELLIA, MD5, SHA256, RSA} crypto_algo;

/* Graph Data Structures */
GHashTable* vertexes;
GQueue* edges;

void error(char *msg) {
    perror(msg);
    syslog(LOG_ERR | LOG_USER, "%s: %m\n", msg);
    exit(1);
}

/* Initialize OpenSSL and Graph Data Structures */
void init() {
    if(!EVP_add_all_ciphers()) error("Error adding ciphers.");
    if(!EVP_add_all_digests()) error("Error adding digests.");

    vertexes = g_hash_table_new(g_str_hash, g_str_equal);
    edges = g_queue_new();
}

/* Generate Random Graph Data */
void generateGraph() {
    srand(time(NULL));

    for (int i = 0; i < MAX_VERTEXES; i++) {
        char buffer[MAX_BUFFER];
        sprintf(buffer, "Vertex%d", rand());
        g_hash_table_insert(vertexes, strdup(buffer), NULL);
    }

    for (int i = 0; i < MAX_EDGES; i++) {
