```C
#include <stdio.h>
#include <curl/curl.h>
#include <pthread.h>
#include <assert.h>
#include <string.h>

struct buffer {
    char *data;
    size_t len;
};

// Initialize curl once, safe to use in multithreaded environment
CURL* init_curl() {
  CURL *curl = curl_easy_init();
  assert(curl);
  return curl;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t total_len = 0;
size_t max_data_size = 1e9; // predefined limits

void* fetch_data(void *param) {
  CURLcode res;
  struct buffer chunk = {0};

  CURL* curl = init_curl();

  curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
  curl_easy_setopt(curl, CURLOPT_WRITEDATA, &chunk);

  res = curl_easy_perform(curl);

  if(res != CURLE_OK) {
    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
  } else {
    pthread_mutex_lock(&mutex);
    total_len += chunk.len;

    if (total_len >= max_data_size) {
      fprintf(stderr, "Maximum data size exceeded\n");
    }

    // Process the data...

    pthread_mutex_unlock(&mutex);
  }
}

// Write callback for libcurl to receive incoming data.
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
  size_t realsize = size * nmemb;
  struct buffer *chunk = (struct buffer *)userp;

  // Reallocate memory to fit the new data
  chunk->data = realloc(chunk->data, chunk->len + realsize + 1);

  if (!chunk->data) {
    fprintf(stderr, "Not enough memory\n");
    return 0;
  }

  memcpy(&(chunk->data[chunk->len]), contents, realsize);
  chunk->len += realsize;
  return realsize;
}

int main() {
  // Create threads to fetch data concurrently...

  // Join all threads and cleanup resources...
}
```
