// Define the struct for the record
typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

// Database connection info
PGconn* conn = NULL;
char* conninfo = "host=localhost port=5432 dbname=test user=postgres password=secret";

// Thread safe database interaction function
void* fetch_record(void* args) {
    Record* record = (Record*)args;

    // Connect to the database
    conn = PQconnectdb(conninfo);
    if (PQstatus(conn) == CONNECTION_BAD) {
        fprintf(stderr, "Connection to database failed: %s\n",
                PQerrorMessage(conn));
        exit_threadsafe(1);
    }

    // Fetch record
    char query[50];
    sprintf(query, "SELECT * FROM records WHERE key = %d", record->key);
    PGresult* res = PQexec(conn, query);

    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "SELECT failed: %s\n", PQerrorMessage(conn));
        PQclear(res);
        exit_threadsafe(1);
    }

    // Populate record from result
    Record* fetched_record = (Record*)malloc(sizeof(Record));
    fetched_record->offset = atol(PQgetvalue(res, 0, 0));
    fetched_record->key = atoi(PQgetvalue(res, 0, 1));
    fetched_record->value = atoi(PQgetvalue(res, 0, 2));

    // Clean up and exit
    PQclear(res);
    PQfinish(conn);
    return (void*)fetched_record;
}
```
