```csharp
using System.Security.Cryptography;

public class EncryptionService
{
    public byte[] Encrypt(byte[] dataToEncrypt)
    {
        using (Aes aes = Aes.Create())
        {
            ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            return PerformCryptography(dataToEncrypt, encryptor);
        }
    }

    public byte[] Decrypt(byte[] dataToDecrypt)
    {
        using (Aes aes = Aes.Create())
        {
            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            return PerformCryptography(dataToDecrypt, decryptor);
        }
    }

    private byte[] PerformCryptography(byte[] data, ICryptoTransform cryptoTransform)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, cryptoTransform, CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
                cs.Close(); // This will also flush the internal buffer inside MemoryStream to complete encryption/decryption
            }

            return ms.ToArray();
        }
    }
}
```
This is a simple example and doesn't cover all aspects of security, but you can use it as a starting point to build more complex systems.
