            raise Exception(f"Mock for {name} is not registered.")

        return cls._mocks[name]


class TestCase:
    _logger = None

    def __init__(self, test_id):
        self.test_id = test_id
        if TestCase._logger is None:  # Lazy initialization of logger
            TestCase._logger = get_logger(self.__class__.__name__)

    async def run(self):
        raise NotImplementedError("Subclasses should implement this method.")

    @staticmethod
    def retry(retries=3, delay=0.5, backoff=2):
        def decorator(f: Callable[[Any], Any]):
            @wraps(f)
            async def wrapper(*args, **kwargs):
                nonlocal delay
                for _ in range(retries):
                    try:
                        return await f(*args, **kwargs)
                    except Exception as e:
                        await asyncio.sleep(delay)
                        delay *= backoff

            return wrapper

        return decorator
