class ResourceBundle {
public:
    // Loading and managing resources are not shown in this simple example.
    void addResource(std::string key, std::string value) {
        std::lock_guard<std::mutex> lock(mMutex);  // Ensures thread-safe operation.
        mResources[key] = value;
    }

    bool removeResource(std::string key) {
        std::lock_guard<std::mutex> lock(mMutex);  // Ensures thread-safe operation.
        return mResources.erase(key) > 0;
    }

    std::string getResource(std::string key) const {
        std::lock_guard<std::mutex> lock(mMutex);  // Ensures thread-safe operation.
        auto it = mResources.find(key);
        return (it == mResources.end()) ? "" : it->second;
    }

private:
    mutable std::mutex mMutex;  // Protects access to shared data from multiple threads.
    std::map<std::string, std::string> mResources;
};
```
