public class DataValidationService {
    private static final int TOP_N = 10000;
    private static PriorityQueue<Integer> topIntegers = new PriorityQueue<>(); // Assume this data structure is efficient for your use case

    public static synchronized void validateAndStore(int data) {
        if (isValid(data)) {
            store(data);
        }
    }

    private static boolean isValid(int data) {
        // Implement the validation logic here.
        return true;
    }

    private static void store(int data) {
        if (topIntegers.size() < TOP_N) {
            topIntegers.offer(data);
        } else if (data > topIntegers.peek()) {
            topIntegers.poll(); // Remove the smallest integer currently in the queue.
            topIntegers.offer(data); // Add the new integer to maintain the size limit.
        }
    }
}
