using Newtonsoft.Json;

public class DynamicFileUploader : IDisposable
{
    private readonly ILogger _logger;
    private readonly Random _randomGenerator;
    private readonly IRestClient _restClient;
    private string _filePath;

    // Constructor with dependencies injected
    public DynamicFileUploader(ILogger logger, string filePath)
    {
        _logger = logger;
        _randomGenerator = new Random();
        _restClient = new RestClient("http://example.com");
        _filePath = filePath;
    }

    public int GenerateRandomInt(int min, int max, bool inclusive)
    {
        if (min > max) 
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        return inclusive ? _randomGenerator.Next(min, max + 1) : _randomGenerator.Next(min, max);
    }

    public float GenerateRandomFloat(float min, float max, bool inclusive)
    {
        if (min > max) 
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        var randomValue = (float)(_randomGenerator.NextDouble() * (max - min) + min);

        return inclusive ? MathF.Round(randomValue, 2) : randomValue;
    }

    public async Task<bool> UploadFileAsync()
    {
        var request = new RestRequest("resource", Method.POST);
        byte[] fileBytes = File.ReadAllBytes(_filePath);
        request.AddParameter("application/octet-stream", fileBytes, ParameterType.RequestBody);

        try
        {
            var response = await _restClient.ExecuteAsync(request);

            if (response.IsSuccessful) 
                return true;

            // handle failure here and retry with exponential backoff or another strategy
            throw new Exception("Upload failed");
        }
        catch (Exception ex)
        {
            _logger.Error($"Failed to upload file: {ex.Message}", ex);
            return false;
        }
    }

    public void Dispose()
    {
