```c
#include <stdio.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>
#include <jansson.h>
#include <syslog.h>

// Structure to hold command details
typedef struct {
    char* cmd;  // Command string
    pid_t pid;  // Process ID of the command execution
} Command;

// Array to hold commands to execute
Command commands[1024];  
int num_commands = 0;  

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety

// Function to execute command asynchronously
void* execute_command(void* arg) {
    Command* cmd = (Command*)arg;

    pid_t pid = fork();
    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", cmd->cmd, NULL);  // Execute command in child process
    } else {
        cmd->pid = pid;
    }

    return NULL;
}

// Function to handle system signals
void signal_handler(int signum) {
    for (int i = 0; i < num_commands; ++i) {
        kill(commands[i].pid, SIGKILL);  // Send SIGKILL to all child processes
    }

    exit(signum);
}

// Function to fetch commands from configuration management system
void fetch_commands() {
    CURL* curl = curl_easy_init();
    if (curl) {
        // TODO: Set up the necessary options and perform the request here.

        // After receiving response, parse it using json parsing library like jansson
        /*json_t *root;
        json_error_t error;
        root = json_loads(response, 0, &error);*/
    }

    curl_easy_cleanup(curl);
}

// Main function to start the service
int main() {
    signal(SIGINT, signal_handler);  // Set up signal handler for graceful shutdown

    fetch_commands();

    pthread_t threads[num_commands];

    for (int i = 0; i < num_commands; ++i) {
        if (pthread_create(&threads[i], NULL, execute_command, &commands[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_commands; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2;
        }
    }

    pthread_mutex_destroy(&lock);

    return 0;
}
```
