```csharp
using Microsoft.AspNetCore.Mvc;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using StackExchange.Redis;
using System.Data.SqlClient;
using Polly;
using Newtonsoft.Json;
using Microsoft.Extensions.Configuration;

namespace HashService.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class HashingController : ControllerBase
    {
        private readonly IConnectionMultiplexer _redis;
        private readonly SqlConnection _sqlConnection;
        private readonly IDatabaseAsync redisDb;
        private readonly string hashStorageKey = "hashes";

        public HashingController(IConfiguration configuration)
        {
            _redis = ConnectionMultiplexer.Connect(configuration["Redis:ConnectionString"]);
            _sqlConnection = new SqlConnection(configuration.GetConnectionString("DefaultConnection"));
            redisDb = _redis.GetDatabase();
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody] string data)
        {
            // Compute the SHA256 hash and save it to Redis cache asynchronously
            var policy = Policy
                .Handle<RedisConnectionException>()
                .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

            await policy.ExecuteAsync(async () =>
            {
                var hash = ComputeHash(data);
                // Save to Redis cache
                await redisDb.ListRightPushAsync(hashStorageKey, JsonConvert.SerializeObject(hash));
            });

            // Save the metadata to SQL Server database
            using (var command = new SqlCommand("INSERT INTO Hashes (Hash) VALUES (@hash)", _sqlConnection))
            {
                command.Parameters.AddWithValue("@hash", hash);
                await _sqlConnection.OpenAsync();
                await command.ExecuteNonQueryAsync();
            }

            return Ok(hash);
        }

        private string ComputeHash(string data)
        {
            using (SHA256 sha256 = SHA256.Create())
            {
                byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(data));
                StringBuilder builder = new StringBuilder();
                for (int i = 0; i < bytes.Length; i++)
                {
                    builder.Append(bytes[i].ToString("x2"));
                }
                return builder.ToString();
            }
        }
    }
}
```
