class CacheAndRetrieve {
private:
    redox::Redox client;

public:
    CacheAndRetrieve() : client(nullptr) {}

    void connect() { 
        if (!client.connect("localhost", 6379)) {
            throw std::runtime_error("Failed to connect to Redis server");
        }
    }

    bool cacheAndRetrieve(const std::string& key, const std::string& dataPayload, int expirationTime) {
        client.command({"SET", key, dataPayload, "EX", std::to_string(expirationTime)}, nullptr); // Set the data in Redis with an expiry time
        std::string retrievedData;

        if (client.get(key, retrievedData)) {
            // If successful, return true and provide the retrieved data to the caller
            return true;
        } else {
            throw std::runtime_error("Failed to retrieve key from Redis");
        }
    }
};
