    private readonly ILogger<OrderProcessingService> _logger;

    public OrderProcessingService(IPaymentGateway paymentGateway, 
                                  IInventoryService inventoryService, 
                                  ILogisticsPlatform logisticsPlatform,
                                  ILogger<OrderProcessingService> logger)
    {
        _paymentGateway = paymentGateway;
        _inventoryService = inventoryService;
        _logisticsPlatform = logisticsPlatform;
        _logger = logger;
    }

    public async Task<OrderProcessingResult> HandleOrderRequestAsync(Order order)
    {
        try
        {
            // Validate and sanitize input data.

            // Process inventory management.
            await _inventoryService.UpdateInventoryAsync(order);

            // Process payment gateways.
            var paymentResult = await _paymentGateway.ProcessPaymentAsync(order.PaymentDetails);
            if (!paymentResult.IsSuccessful)
            {
                return new OrderProcessingResult
                {
                    IsSuccessful = false,
                    Message = $"Failed to process payment: {paymentResult.Message}"
                };
            }

            // Process logistics platform.
            var shippingResult = await _logisticsPlatform.DispatchOrderAsync(order);
            if (!shippingResult.IsSuccessful)
            {
                return new OrderProcessingResult
                {
                    IsSuccessful = false,
                    Message = $"Failed to dispatch order: {shippingResult.Message}"
                };
                }

            // Log the successful transaction.
            _logger.LogInformation($"Order processed successfully with ID: {order.Id}");

            return new OrderProcessingResult
            {
                IsSuccessful = true,
                Message = $"Order processed successfully with ID: {order.Id}"
            };
        }
        catch (Exception ex)
        {
            // Log the exception and throw for further handling.
            _logger.LogError(ex, $"An error occurred while processing order with ID: {order.Id}");
            throw;
        }
    }
}
