typedef struct resource_bundle {
    int id;
    char* content;
    pthread_mutex_t mutex;
} resource_bundle_t;

void init_resource_bundle(resource_bundle_t *bundle, int id) {
    bundle->id = id;
    bundle->content = NULL;
    pthread_mutex_init(&bundle->mutex, NULL);
}

void set_content(resource_bundle_t *bundle, char* content) {
    pthread_mutex_lock(&bundle->mutex);
    bundle->content = content;
    pthread_mutex_unlock(&bundle->mutex);
}

char* get_content(resource_bundle_t *bundle) {
    char* result;
    pthread_mutex_lock(&bundle->mutex);
    result = bundle->content;
    pthread_mutex_unlock(&bundle->mutex);
    return result;
}
```
