```javascript
const express = require('express');
const app = express();
const session = require('express-session');
const jwt = require('jsonwebtoken');
const Firestore = require('@google-cloud/firestore');
const firestore = new Firestore();
const passport = require('passport');
const GoogleStrategy = require('passport-google-oauth20').Strategy;

app.use(session({
  secret: 'yoursecret',
  resave: false,
  saveUninitialized: true,
}));

app.use(passport.initialize());
app.use(passport.session());

passport.serializeUser((user, done) => {
  done(null, user);
});

passport.deserializeUser((user, done) => {
  done(null, user);
});

// Configure Google OAuth strategy
passport.use(new GoogleStrategy({
    clientID: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    callbackURL: "/auth/google/callback"
  },
  (accessToken, refreshToken, profile, done) => {
    // Verify user and create session here
    const user = { id: profile.id };
    return done(null, user);
  }
));

app.get('/auth/google', passport.authenticate('google', { scope : ['profile'] }));

app.get('/auth/google/callback', 
passport.authenticate('google', { failureRedirect: '/login' }), (req, res) => {
    const token = jwt.sign({ userId: req.user.id }, 'yoursecret');
    res.redirect(`https://example.com/auth?token=${token}`); // redirect with JWT in URL for MFA 
});

app.post('/logout', (req, res) => {
  req.session.destroy();
  res.send('Logged out');
});

// Middleware to check JWT and attach user data to request object
const authMiddleware = async (req, res, next) => {
  const token = req.header('Authorization').replace('Bearer ', '');
  try {
    const decodedToken = jwt.verify(token, 'yoursecret');
    // Fetch user data from Firestore or other external store
    const snapshot = await firestore.collection('users').doc(decodedToken.userId).get();
    if (!snapshot.exists) {
      throw new Error('User not found');
    } else {
      req.user = snapshot.data();
      next();
    }
  } catch (e) {
    res.status(401).send({ error: 'Please authenticate.' });
  }
};
app.use(authMiddleware);
```
