    @Async("threadPoolTaskExecutor")
    public void processData(String message) {
        try{
            Integer data = Integer.parseInt(message);

            if(!top10Integers.contains(data)) {
                top10Integers.add(data);

                if(top10Integers.size() > 10_000) {
                    top10Integers.poll(); // remove the smallest integer from queue.
                }
            }

            eventDrivenFramework.publishEvent("DATA_PROCESSED", data);
        } catch (Exception e) {
            logger.error("Error while processing data: ", e);
            eventDrivenFramework.retransmitMessage(message); // Retransmitting message for any error or failure in processing.
        }
    }

    @KafkaListener(topics = "${kafka.topic}", groupId = "group_id")
    public void consume(String message) {
        processData(message);
    }

