```csharp
using System;
using System.Threading;

public class SemaphoreManager
{
    private Semaphore semaphore = new Semaphore(1, 1); // Initialize with one permit and a maximum of one permit

    public void Enter() {
        semaphore.WaitOne(); // Wait until it is safe to enter.
    }

    public void Leave() {
        semaphore.Release(); // Notify the manager that you are leaving so others can enter.
    }
}
```
