```c
#include <sys/types.h>
#include <unistd.h>
#include <sys/wait.h>
int run_in_background(char* cmd) {
    pid_t pid = fork();

    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        exit(127);  // exec only returns on error
    } else if (pid > 0) {
        waitpid(pid, NULL, WNOHANG);
        return 1;
    } else {
        return 0;  // Fork failed.
    }
}
```
