```rust
use std::collections::HashMap;
use oauth2::TokenEndpointRequest;
use reqwest::Client;
use tokio::sync::RwLock;
use hyper::rt::HttpsConnector;
use trust_dns_resolver::config::*;

pub struct LLMPCertificateIR {
    pub oauth2: OAuth2,
    pub kms: KMSClient,
    pub cache: RwLock<HashMap<String, String>>, // Cache for keys and certificates.
}

impl LLMPCertificateIR {
    async fn fetch_key(&self, key_id: &str) -> Result<String, Error> {
        let mut tries = 0;
        loop {
            match self.kms.get_key(key_id).await {
                Ok(result) => return Ok(result),
                Err(error) if error.is_unauthorized() || error.is_not_found() => 
                    return Err(error),
                Err(error) if tries < 3 => 
                    std::thread::sleep(std::time::Duration::from_secs(2 * (tries + 1))),
                Err(e) => return Err(e),
            }
            tries += 1;
        }
    }

    async fn fetch_token(&self, auth_service: &str) -> Result<String, Error> {
        let token_req = TokenEndpointRequest::new()
            .client_id("your-client-id")
            .grant_type(GrantType::ClientCredentials);

        match self.oauth2.get_token(auth_service, token_req).await {
            Ok(result) => return Ok(result),
            Err(error) if error.is_unauthorized() || error.is_forbidden() => 
                return Err(error),
            Err(e) => return Err(e),
        }
    }

    async fn get_certificate(&self, key: &str, grammar: &str) -> Result<Certificate, Error> {
        let lexer = Lexer::new();
        let parser = Parser::new();

        match lexer.parse(grammar).await {
            Ok(result) => return Ok(result),
            Err(error) if error.is_bad_request() => 
                return Err(error),
            Err(e) => return Err(e),
        }

        match parser.parse(grammar).await {
            Ok(ir) => self.kms.sign_with_key(&ir, &key).await,
            Err(error) if error.is_bad_request() => 
                return Err(error),
            Err(e) => return Err(e),
        }
    }
}
```
Please note that this is a simplified version of the code and it doesn't cover all aspects you mentioned (like logging, network failures handling, integration with third-party services, etc.). Also, some parts are placeholders for illustrative purposes only. 

