['```php
<?php 
// Start session if not already started
if (session_status() == PHP_SESSION_NONE) {
    session_start();
}

function renderFooterWithUserAuth($scripts, $clientId, $clientSecret) {
    $tokenUrl = 'https://auth.example.com/oauth2';
    $userInfoUrl = 'https://api.example.com/users';

    try {
        // Fetch OAuth token
        $curlTokenHandler = curl_init($tokenUrl);
        curl_setopt($curlTokenHandler, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($curlTokenHandler, CURLOPT_POSTFIELDS, [
            'client_id' => $clientId, 
            'client_secret' => $clientSecret,
            'grant_type' => 'authorization_code',
            'code' => $_GET['code']
        ]);
        $response = curl_exec($curlTokenHandler);

        if (curl_errno($curlTokenHandler)) {
            throw new Exception('Error fetching token: '.curl_error($curlTokenHandler));
        }
        $tokenResponse = json_decode($response, true);

        // Store access token in session
        $_SESSION['access_token'] = $tokenResponse['access_token'];

        // Fetch user information using the access token
        $userCurlHandler = curl_init($userInfoUrl.'?access_token='.$tokenResponse['access_token']);
        curl_setopt($userCurlHandler, CURLOPT_RETURNTRANSFER, true);
        $response = curl_exec($userCurlHandler);

        if (curl_errno($userCurlHandler)) {
            throw new Exception('Error fetching user info: '.curl_error($userCurlHandler));
        }
        $userInfoResponse = json_decode($response, true);

        // Render footer section with scripts and user information
        echo '<footer>';
        foreach ($scripts as $script) {
            if (preg_match('/^https?:\/\//', $script)) {
                echo "<script src='$script'></script>";
            } else {
                throw new Exception('Invalid script source: '.$script);
            }
        }
        echo '<p>User Info: '.htmlspecialchars($userInfoResponse['info']).'</p>';
        echo '</footer>';
    } catch (Exception $e) {
        // Handle exceptions and display error message
        echo "Error occurred: ". htmlspecialchars($e->getMessage());
        return false;
    } finally {
        curl_close($curlTokenHandler);
        curl_close($userCurlHandler);
    }
}
?>
``` 

This is a basic implementation and may need to be adjusted based on the specifics of your application, such as the structure of the OAuth token endpoint response and user information API. Also, it's important to note that this code doesn't implement any form of rate limiting or other performance optimizations, which you should consider if your application is expected to handle a high volume of requests.
']

