class DataProcessor {
public:
    void processData(int data) {
        const std::lock_guard<std::mutex> lock(m);
        if (data > 0 && data <= 50000 && uniqueSet.find(data) == uniqueSet.end()) {
            uniqueSet.insert(data);
            pq.push(data);
            if (pq.size() > 50'000) {
                uniqueSet.erase(pq.top());
                pq.pop();
            }
        }
    }
private:
