    std::priority_queue<int, std::vector<int>, std::greater<>> pq;
    std::mutex m;
};

class AttackSelector {
public:
    AttackSelector() : dist(0, attacks.size() - 1) {}

    void addAttack(std::string attackName) {
        attacks.emplace_back(attackName);
    }

    std::function<void()> selectRandomAttack() {
        if (clock::now() > lastSelectionTime + cooldown) {
            lastSelectionTime = clock::now();
            selectedAttack = dist(gen);
        }

        return [this]() { 
            std::cout << "Performing attack: " << attacks[selectedAttack] << std::endl;
        };
    }

private:
    using clock = std::chrono::system_clock;
    const std::chrono::seconds cooldown{12};
    clock::time_point lastSelectionTime = clock::now() - cooldown;
    int selectedAttack = 0;

    std::vector<std::string> attacks{"attack1", "attack2", "attack3"};
    std::uniform_int_distribution<> dist;
};
```

In the given example, the DataProcessor class uses a priority queue and an unordered set to maintain the top 50,000 unique valid integers. The AttackSelector class selects one of several predefined attacks with a cooldown period of 12 seconds. This code does not include logging or error handling as it is quite complex to fully implement this in such a small space and requires a full application design which goes beyond the scope of this task.
