```javascript
const express = require('express');
const bodyParser = require('body-parser');
const multer = require('multer');
const { Storage } = require('@google-cloud/storage');
const sharp = require('sharp');
const redis = require('redis');
const rateLimit = require("express-rate-limit");

// Configure Multer
const upload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 5 * 1024 * 1024 }, // Maximum file size is 5MB
});

// Configure Redis Client
const redisClient = redis.createClient();
redisClient.on('error', (err) => console.log(`Redis Error: ${err}`));

// Rate Limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
});

const app = express();
app.use(bodyParser.json());
app.use(limiter); // Apply rate limiting middleware to all requests

// Upload an Image
app.post('/upload', upload.single('image'), (req, res) => {
    const file = req.file;
    if (!file) return res.status(400).send('No image uploaded');

    // Process the image and send back metadata
    sharp(file.buffer)
        .resize(250, 250)
        .toBuffer()
        .then((data) => {
            const storage = new Storage();
            const bucketName = 'your-bucket-name';

            const blob = storage.bucket(bucketName).file(`${Date.now()}-image`);
            const blobStream = blob.createWriteStream({ resumable: false });

            blobStream.on('error', (err) => {
                res.status(500).send({ error: err });
            });

            blobStream.on('finish', () => {
              const publicUrl = `https://storage.googleapis.com/${bucketName}/${blob.name}`;
              // Save the URL and other metadata to Redis
              redisClient.set(publicUrl, JSON.stringify({
                url: publicUrl,
                size: file.size,
                type: file.mimetype,
              }));

              res.status(200).send('Image uploaded successfully');
            });

            blobStream.end(data);
        })
        .catch((err) => {
            res.status(500).send({ error: err });
        });
});

app.listen(3000, () => console.log('Server is running'));
```

This code doesn't handle all the scenarios you asked for. For instance, it does not include a mechanism to upload from external APIs or different cloud storage services due to complexity in those areas. Similarly, it lacks detailed configuration and integration with various infrastructure tools like Kubernetes, observability tools, etc. 

