using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using System.Data.SqlClient;
using System.Security.Cryptography.X509Certificates;
using System.Net.Security;

public class DataProcessingService : ControllerBase
{
    private readonly DatabaseContext _context;

    public DataProcessingService(DatabaseContext context) 
    {
        _context = context;
    }

    [HttpPost]
    public async Task<IActionResult> ProcessData([FromBody] byte[] data)
    {
        if (data == null || data.Length == 0) 
        {
            return BadRequest();
        }

        var secureConnection = new SqlConnection(ConfigurationManager.ConnectionStrings["SecureDatabase"].ToString());
        await secureConnection.OpenAsync(SqlAuthenticationMethod.ActiveDirectoryInteractive);

        using (var command = new SqlCommand("INSERT INTO DataTable VALUES(@data)", secureConnection)) 
        {
            command.Parameters.AddWithValue("@data", data);
            var rowsAffected = await command.ExecuteNonQueryAsync();

            if (rowsAffected > 0) 
            {
                return Ok();
            } 
            else 
            {
                return StatusCode(500, "Failed to process data");
            }
        }
    }
}
```
