1. Designing a resilient decryption pipeline in C#:
```csharp
public async Task<string> DecryptAndDeserializeAsync(byte[] encryptedData, byte[] key, byte[] iv)
{
    using (Aes aes = Aes.Create())
    {
        aes.KeySize = 256; // in bits
        aes.BlockSize = 128; // in bits
        aes.Padding = PaddingMode.PKCS7;
        aes.Key = key;
        aes.IV = iv;

        using (ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
        {
            string result = "";

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        result = await srDecrypt.ReadToEndAsync();
                    }
                }
            }

            return result;
        }
    }
}
```
