public static async Task RetryOnException<T>(Func<Task<T>> action, int maxRetries)
{
    for (int i = 0; i < maxRetries; i++)
    {
        try
        {
            await action();
            break;
        }
        catch (Exception ex) when (i != maxRetries - 1) // Not the last iteration
        {
            Console.WriteLine($"An error occurred: {ex}. Retrying in {500 * (i + 1)}ms...");
            await Task.Delay(500 * (i + 1));
        }
    }
}
