        _externalDependencyService = externalDependencyService;
        _monitoringService = monitoringService;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken) {
        while (!stoppingToken.IsCancellationRequested) {
            try {
                if (_authService.Authenticate()) {
                    var connection = await _connectionFactory.GetConnectionAsync();
                    var pduData = await connection.QueryAsync<NFAPI_CRC_INDICATION_PDU_T>("SELECT * FROM PDUTable"); // Use actual query here

                    foreach (var pdu in pduData) {
                        if (_externalDependencyService.IsValid(pdu)) {
                            await _monitoringService.RecordPerformanceMetricsAsync(connection, pdu);
                        } else {
                            _logger.LogError("Invalid PDU data detected!");
                            await _authService.DegradeOperation(pdu);
                        }
                    }
                } else {
                    _logger.LogWarning("Authentication failed.");
                    await Task.Delay(_configuration.GetValue<int>("RetryInterval"), stoppingToken);
                }
            } catch (Exception ex) {
                _logger.LogError(ex, "Unhandled exception occurred!");
            }
        }
    }
}
