```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

typedef struct {
    sem_t sem;
    char* name;
} Semaphore;

Semaphore* createSemaphore(int initialValue, int maxLimit, char* name) {
    if (initialValue < 0 || maxLimit <= 0 || name == NULL) {
        printf("Invalid parameters\n");
        return NULL;
    }

    Semaphore* sem = malloc(sizeof(Semaphore));
    if (sem_init(&sem->sem, 0, initialValue) != 0 || pthread_mutex_init(&sem->lock, NULL) != 0) {
        printf("Failed to create semaphore\n");
        return NULL;
    }

    sem->name = name;
    sem->maxLimit = maxLimit;
    return sem;
}
