// Validator for the resource model
public class ResourceValidator : AbstractValidator<Resource>
{
    public ResourceValidator()
    {
        RuleFor(x => x.Id).NotEmpty();
        RuleFor(x => x.Status).Must(status => new[] { "active", "deleted" }.Contains(status));
        // Define other rules as needed by your application
    }
}

// API Controller
[Route("api/resources")]
public class ResourcesController : ControllerBase
{
    private readonly MyDbContext _context;
    private readonly IValidator<Resource> _validator;

    public ResourcesController(MyDbContext context, IValidator<Resource> validator)
    {
        _context = context;
        _validator = validator;
    }

    // PUT endpoint to update a resource by its ID
    [HttpPut("{id}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Resource resource)
    {
        if (resource == null || id != resource.Id) return BadRequest();

        var validationResult = _validator.Validate(resource);
        if (!validationResult.IsValid) return BadRequest(validationResult.Errors);

        // Find the existing resource in the database
        var existingResource = await _context.Resources.FindAsync(id);
        if (existingResource == null) return NotFound();

        // Compare versions to prevent conflicts
        if (resource.Version != existingResource.Version) return Conflict("The version of the resource has been updated by another user.");

        // Apply updates and save changes to the database
        _context.Entry(existingResource).CurrentValues.SetValues(resource);
        await _context.SaveChangesAsync();

        return Ok();
    }
}

// Method to execute a byte array query on a database server and get a DataTableReader object
public async Task<DataTableReader> ExecuteQueryAsync(byte[] sqlCommand, string connectionString)
{
    using (var context = new MyDbContext())
    {
        var commandText = Encoding.UTF8.GetString(sqlCommand);
        return await context.Database.ExecuteSqlInterpolatedAsync($"EXECUTE({commandText}) AT [{connectionString}]");
    }
}
```

