#include <iostream>
#include <string>
#include "json/json.h"

bool verifyOAuth2Token(std::string json_str) {
    Json::Value root;
    Json::Reader reader;
    bool parseSuccess = reader.parse(json_str, root);

    if(!parseSuccess){
        std::cout << "Failed to parse JSON string" << std::endl;
        return false;
    }

    // Check for all required fields and their values
    bool accessTokenExists = root.isMember("access_token");
    bool expiresInIsPositiveInteger = (root["expires_in"].isInt() && root["expires_in"].asInt() > 0);
    bool tokenTypeIsBearer = (root["token_type"].isString() && root["token_type"].asString() == "Bearer");

    // Refresh Token is optional so only check if it exists
    bool refreshTokenExists = root.isMember("refresh_token"); 

    return accessTokenExists && expiresInIsPositiveInteger && tokenTypeIsBearer && refreshTokenExists;
}
```
This function uses the JSON library to parse a string as JSON and then checks whether all required fields (access_token, expires_in, token_type) exist and if they have the correct values. It returns true only when all checks pass, false otherwise. This is an oversimplified example, in reality, you'd also need to handle network requests to verify the tokens with the OAuth2 server.
