["Here's an abstract overview for the service:

```javascript
const express = require('express');
const axios = require('axios');
const vm = require('vm');
const cacheManager = require('cache-manager');
const memoryCache = cacheManager.caching({ store: 'memory', max: 100, ttl: 60/*seconds*/ });

class LibraryService {
    constructor() {
        this.app = express();
        this.setupRoutes();
    }

    setupRoutes() {
        this.app.get('/api/library/:id', async (req, res) => {
            const libraryId = req.params.id;

            let cachedResult = await memoryCache.get(libraryId);
            if (cachedResult) {
                return res.send({ status: 'success', data: cachedResult });
            }

            try {
                const response = await axios.get('https://third-party-api.com/' + libraryId, { 
                    auth: {
                        username: process.env.API_USERNAME,
                        password: process.env.API_PASSWORD
                    } 
                });

                const sandbox = vm.createContext({ require });
                vm.runInContext(response.data, sandbox);

                memoryCache.set(libraryId, sandbox);

                res.send({ status: 'success', data: sandbox });
            } catch (error) {
                console.log('Error fetching library: ', error);
                res.status(500).send({ 
                    status: 'error', 
                    message: 'An error occurred while fetching the library' 
                });
            }
        });
    }

    start() {
        const port = process.env.PORT || 3000;
        this.app.listen(port, () => console.log(`App listening on PORT ${port}`));
    }
}

const libraryService = new LibraryService();
