```cpp
#include <dlfcn.h>
#include <thread>
#include <mutex>
#include <vector>
#include <condition_variable>
#include <filesystem>
#include <string>
// Define a struct to hold library information
struct Lib {
    void *handle;
    std::function<void()> func; // Function pointer for the function in the shared library
};

class Loader {
public:
    void loadLibrary(std::string path) {
        std::lock_guard<std::mutex> lock(mtx);
        void *handle = dlopen(path.c_str(), RTLD_LAZY);
        if (!handle) {
            throw std::runtime_error("Failed to load library: " + path);
        }

        // Assuming each library has a function 'init' that initializes it
        void *func = dlsym(handle, "init");
        Lib lib;
        lib.handle = handle;
        lib.func = reinterpret_cast<void(*)()>(func);

        libraries.push_back(lib);
    }

    void callFunctionFromLibraries() {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto &lib : libraries) {
            // Call the function in each library
            lib.func();
        }
    }
private:
    std::vector<Lib> libraries;
    std::mutex mtx;
};
```

This is a basic code snippet of how you can load and manage multiple shared libraries at runtime using C++17's dlopen and dlsym. For your system, you would probably want to use threads for concurrent invocations or consider an event-driven approach for async operations with asio library, filesystem module to read files from a directory, and robust error handling mechanisms for logging and recovery.
