      return res.json(JSON.parse(cachedData));
    } else { // no data in cache, fetch from weather APIs
      const apiKeys = ['apiKey1', 'apiKey2']; // add your API keys here

      for (let key of apiKeys) {
        try {
          let response;

          if(key === 'apiKey1'){ 
            response = await limiter.schedule(() => 
              axios.get(`https://api1.com/weather?location=${location}&appid=${key}`)
            ); // use api1
          } else {
            response = await limiter.schedule(() => 
              axios.get(`https://api2.com/weather?location=${location}&appid=${key}`) 
            ); // use api2
          }

          if (response.status === 200){
            client.setex(location, 3600, JSON.stringify(response.data));
            return res.json(response.data);
          } else {
            req.logger.error("Error in fetching data from API");
            throw new Error('Failed to fetch weather');
          }
        } catch (err) {
          continue; // try the next API key if error occurred with current one
        }
      }

      return res.status(500).json({error: 'Failed to fetch weather data'});
    }
  });
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Listening on port ${port}...`));
