#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    // Your data structure for heterogeneous data objects goes here
} DataObject;

// Global variables for managing data processing
DataObject* queue[100];
atomic_int front = 0, rear = -1, count = 0;
pthread_mutex_t lock;

void processData(DataObject* obj) {
    // Implement your logic to handle and process the heterogeneous data objects here
}

// Function executed by each thread
void* worker(_Atomic int* ptr) {
    DataObject *obj;

    while (1) {
        pthread_mutex_lock(&lock);

        // Check if there's more data to process
        if(count == 0) {
            pthread_mutex_unlock(&lock); 
            continue;
        }

        // Get the next piece of data and process it
        obj = queue[front];
        front = (front+1)%100;
        count--;
        pthread_mutex_unlock(&lock);

        processData(obj);
    }

    return NULL;
}

int main() {
    // Initialize mutex and threads
    pthread_t threads[5];
    int rc, t;

    if (pthread_mutex_init(&lock, NULL) != 0){
        printf("\n Mutex init failed\n");
        return 1;
    }

    for(t=0; t<5; t++){
        rc = pthread_create(&threads[t], NULL, worker, NULL);

        if (rc){
            printf("ERROR; return code from pthread_create() is %d\n", rc);
            exit(-1);
        }
    }

    // Simulate adding data to the queue
    for(int i=0; i<250; ++i){
        DataObject* obj = malloc(sizeof(DataObject));

        pthread_mutex_lock(&lock);
        rear = (rear+1)%100;
        queue[rear] = obj;
        count++;
        pthread_mutex_unlock(&lock);
    }

    // Wait for all threads to finish and clean up
    for(t=0; t<5; t++){
        pthread_join(threads[t], NULL);
    }
    pthread_mutex_destroy(&lock);
}
``` 

