#include <vector>

std::vector<int> chunkData(int totalSize, int optimalChunk) {
    std::vector<int> chunks;
    while (totalSize > 0) {
        int chunk = std::min(totalSize, optimalChunk);
        chunks.push_back(chunk);
        totalSize -= chunk;
