// Define log level constants
enum LogLevel {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
};

void logMessage(enum LogLevel level, const char* message, ...) {
    va_list args;
    va_start(args, message);

    FILE* errorLog = fopen("error.log", "a");
    if (errorLog == NULL) {
        // Could not open the file for appending, print to stderr instead
        vfprintf(stderr, message, args);
        va_end(args);
        return;
    }

    const char* logLevelStr = "";
    switch (level) {
        case LOG_INFO: 
            logLevelStr = "INFO"; break;
        case LOG_WARNING: 
            logLevelStr = "WARN"; break;
        case LOG_ERROR: 
            logLevelStr = "ERR"; break;
    }

    char fullMessage[1024];
    snprintf(fullMessage, sizeof(fullMessage), "[%s] %s\n", logLevelStr, message);

    vfprintf(errorLog, fullMessage, args);
    fclose(errorLog);
    va_end(args);
}
```
This code will write messages to a file named "error.log". The `enum LogLevel` is used to set the type of log (info, warning, error). The `...` in the function parameters indicate that it can take any number and type of arguments. These arguments are accessed using a special macro called `va_start/va_end` pair which must be included in your code after including `stdarg.h`. 

The message is formatted into a string, then written to the error log file (or stderr if it cannot be opened).
