```java
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.apache.kafka.clients.producer.Producer;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

public class KafkaLogging {
    private static final Logger logger = LogManager.getLogger(KafkaLogging.class);

    public static void main(String[] args) {
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("acks", "all");
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        Producer<String, String> producer = new KafkaProducer<>(props);

        try {
            for (long i = 0; i < 100; i++) {
                RecordMetadata metadata = producer.send(new ProducerRecord<>("my-topic", "key-" + i, "value-" + i)).get();
                logger.info("Sent record to topic {} at offset {}", metadata.topic(), metadata.offset());
            }
        } finally {
            producer.flush();
            producer.close();
        }
    }
}
```
This is a very basic example and doesn't cover all the requirements you mentioned such as multi-tenancy, distributed tracing, error handling, etc. To build a production grade system, you would need to extend this code significantly with additional features like buffering logs locally before sending them to Kafka, implementing multi-tenant support using separate topics or partitions for different tenants, integrating with ELK stack for analysis and alerting, supporting dynamic configuration updates, etc.
