const express = require('express');
const app = express();
const cache = require('ioredis')(process.env.REDIS_URL); // replace with your Redis URL
const { AsyncRetry } = require('async-retry');
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const axios = require('axios').default;

app.use(express.json()); // to support JSON-encoded bodies

// This route will handle the test run request
app.post('/api/tests', async (req, res) => {
  try {
    const { testId } = req.body;

    // Run the tests asynchronously using a worker thread pool
    const workerPoolSize = 10;
    const workerPayloads = [];
    for (let i = 0; i < workerPoolSize; i++) {
      workerPayloads.push(i);
    }

    // Create and start the worker threads
    const workers = workerPayloads.map((payload, index) => {
      return new Promise((resolve, reject) => {
        const worker = new Worker(__dirname + '/workerThread.js', { workerData: { payload } });

        // Listen for messages from the worker thread
        worker.on('message', resolve);
        worker.on('error', reject);
        worker.on('exit', (code) => {
          if (code !== 0) {
            reject(new Error(`Worker stopped with exit code ${code}`));
          }
        });
      });
    });

    // Wait for all workers to finish and collect their results
    const workerResults = await Promise.all(workers);

    // Parse the results and send them back in the response
    res.json({ testId, workerResults });
  } catch (err) {
    console.error('Error handling request', err);
    res.status(500).send({ error: 'An unexpected error occurred' });
  }
});
```

