['This problem requires comprehensive coding experience across several areas such as backend development with Node.js/Python (Flask), Docker configuration, frontend UI design using React and OAuth2 integration. The following is just a simplified example of how such an API could be implemented, you would need to further refine and adjust the code based on your actual needs:

```javascript
// server.js
const express = require('express');
const app = express();
const crypto = require('crypto');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const fs = require('fs');
const util = require('util');

// Middleware for token verification
app.use((req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (token == null) return res.sendStatus(401);

    jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
        if (err) return res.sendStatus(403);
        req.user = user;
        next();
    });
});

app.post('/encrypt', async (req, res) => {
    const iv = crypto.randomBytes(16);
    const passwordData = await bcrypt.hash(req.body.password, 10);
    const key = crypto.pbkdf2Sync(req.body.password, process.env.ENCRYPTION_SALT, 100000, 32, 'sha512');

    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
    let encrypted = cipher.update(req.body.data);

    encrypted = Buffer.concat([encrypted, cipher.final()]);
    res.send({
        passwordData: passwordData, 
        iv: iv.toString('hex'), 
        data: encrypted.toString('hex')
    });
});

app.post('/decrypt', async (req, res) => {
    const key = crypto.pbkdf2Sync(req.body.password, process.env.ENCRYPTION_SALT, 100000, 32, 'sha51');
    const iv = Buffer.from(req.body.iv, 'hex');
    let decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key), iv);

    let decrypted = decipher.update(req.body.data);
    decrypted = Buffer.concat([decrypted, decipher.final()]);

    res.send({ data: decrypted });
});

app.listen(3000, () => console.log("Server is up and running"));
```
