const getAsync = promisify(client.get).bind(client);
const setexAsync = promisify(client.setex).bind(client);

// Array of weather API endpoints and rate limits
let providers = [
  { endpoint: 'http://api1.com/weather', limit: 5, remaining: 5 },
  { endpoint: 'http://api2.com/weather', limit: 5, remaining: 5 }
];

const app = express();
app.use(express.json());

// Score calculation function for providers
function scoreProvider(provider) {
  // Custom scoring logic here...
}

async function fetchWeatherData() {
  let bestScore = 0;
  let bestProvider = null;

  for (let provider of providers) {
    if (provider.remaining > 0 && provider.score > bestScore) {
      bestScore = provider.score;
      bestProvider = provider;
    }
  }

  // If no suitable provider found, throw an error or handle it gracefully
  if (!bestProvider) {
    console.log('No available weather providers');
    return {};
  }

  let response = await fetch(`${bestProvider.endpoint}?location=san_francisco`);
  bestProvider.remaining--; // Decrement API call limit

  if (response.status === 200) {
    return await response.json();
  } else {
    console.log(`API request failed with status ${response.status}`);
    return {};
  }
}

// Routes
app.get('/weather', async (req, res) => {
  let cachedData = await getAsync('san_francisco');

  if (!cachedData) {
    console.log("Cache miss");

    try {
      const data = await fetchWeatherData();

      // Cache the results for one day
      setexAsync('san_francisco', 86400, JSON.stringify(data));

      res.json({success: true, message: 'Weather data fetched successfully', data});
    } catch (err) {
      console.log(`Fetch failed with error ${err}`);
      return res.status(500).json({success: false, message: err.message});
    }
  } else {
    console.log("Cache hit");

    return res.json({success: true, message: 'Weather data fetched successfully', data: JSON.parse(cachedData)});
  }
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server running on port ${port}`));
```
This example uses the `fetch` API to get weather data from an external API endpoint. It also utilizes Redis for caching the results of previous API calls in order to reduce latency and cost. It implements a basic scoring system for selecting providers based on their remaining call limit, but you would want to replace this with your own custom scoring logic.

