```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t length;
} DynamicArray;

DynamicArray* create_array() {
    DynamicArray* arr = malloc(sizeof(*arr));
    if (arr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    arr->capacity = 1;
    arr->length = 0;
    arr->data = malloc(sizeof(*arr->data) * arr->capacity);

    if (arr->data == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    return arr;
}

void add_item(DynamicArray* arr, int item) {
    // Double capacity once the array is full.
    if (arr->length == arr->capacity) {
        arr->capacity *= 2;

        // Realloc can handle moving of data in memory so that's why we use it instead of malloc and memcpy
        int* new_data = realloc(arr->data, sizeof(*new_data) * arr->capacity);
        if (new_data == NULL) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        arr->data = new_data;
    }

    arr->data[arr->length++] = item;
}

int find_max(DynamicArray* arr) {
    if (arr->length == 0) {
        return -1; // Return a specific value indicating an error
    }

    int max = arr->data[0];
    for (size_t i = 1; i < arr->length; ++i) {
        if (arr->data[i] > max) {
            max = arr->data[i];
        }
    }

    return max;
}

void process_stream() {
    DynamicArray* array = create_array();

    // Assume we are getting data from an external source here.
    int item;
    while (scanf("%d", &item) == 1) { 
        add_item(array, item);

        int max_value = find_max(array);
        printf("Largest value encountered so far: %d\n", max_value);
    }

    // Clean up.
    free(array->data);
    free(array);
}

int main() {
    process_stream();

    return 0;
}
```
