class UserManager {
    private $dbConnection;

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function handleUserRequest(array $requestData): array {
        if (isset($requestData['id'])) {
            return $this->handleExistingUser($requestData);
        } else {
            return $this->createNewUser($requestData);
        }
    }

    private function handleExistingUser(array $data): array {
        // Implement user update/delete operations here
        $result = $this->dbConnection->executeQuery("...", $data['id']);

        if ($result) {
            return ['message' => 'success'];
        } else {
            return ['message' => 'error'];
        }
    }

    private function createNewUser(array $data): array {
        // Implement user creation here
        $this->dbConnection->executeQuery("...", [$data['name'], $data['email'], $data['password']]);

        return ['message' => 'success'];
    }
}

class EventProcessor {
    private $broker;
    private $userManager;

    public function __construct(BrokerInterface $broker, UserManager $userManager) {
        $this->broker = $broker;
        $this->userManager = $userManager;
    }

    public function processEvents() {
        $this->broker->receiveEvent(function ($event) {
            $data = json_decode($event, true);

            if (!empty($data)) {
                echo json_encode($this->userManager->handleUserRequest($data));
            } else {
                // Handle error: decoding failed
                echo json_encode(['message' => 'error']);
            }
        });
    }
}
```
