#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& flist, const std::string& target, const std::string& toInsert) {
    auto prevIt = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == target) {
            // Found the target string, insert 'toInsert' after it and return
            flist.insert_after(it, toInsert);
            return;
        }
        prevIt = it;
    }

    // Target string not found in list, append at end
    flist.insert_after(prevIt, toInsert);
}
``` 

