```c
#include <openssl/evp.h>
#include <string.h>

// Hash function 
int hash_data(const unsigned char *message, size_t message_len, unsigned char **digest, unsigned int *digest_len) {
    EVP_MD_CTX *mdctx;

    if((mdctx = EVP_MD_CTX_new()) == NULL) 
        return 0;

    if(1 != EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL))
        return 0;

    if(1 != EVP_DigestUpdate(mdctx, message, message_len))
        return 0;

    if((*digest = (unsigned char *)OPENSSL_malloc(EVP_MD_size(EVP_sha256()))) == NULL)
        return 0;

    if(1 != EVP_DigestFinal_ex(mdctx, *digest, digest_len))
        return 0;

    EVP_MD_CTX_free(mdctx);
    return 1;
}

// Encryption function 
int encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *key,
            unsigned char *iv, unsigned char *ciphertext) {
   EVP_CIPHER_CTX *ctx;

   int len;
   int ciphertext_len;

   if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

   if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) 
       return 0;

   if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) 
       return 0;

   ciphertext_len = len;

   if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) 
       return 0;

   ciphertext_len += len;

   EVP_CIPHER_CTX_free(ctx);

   return ciphertext_len;
}
```
This is a very basic example. Building your cryptographic library as complex as described in the prompt requires careful consideration of design, security, performance, scalability and robustness issues. You will need to learn about OpenSSL's EVP APIs for crypto operations, threading, networking, memory management and error handling in C, which are advanced topics that you may want to take on separately.
