    def retry(operation):
        @wraps(operation)
        def wrapped(*args, **kwargs):
            last_raised = None

            for _ in range(self.retry_count):
                try: 
                    return operation(*args, **kwargs)
                except Exception as e:
                    print("Exception raised during API call. Retrying...")
                    last_raised = e
            raise last_raised
        return wrapped

