        // ...
    }

    std::string get(const std::string& key) {
        // ...
    }
};

class CacheManager {
private:
    std::unique_ptr<CacheBackend> cache;
    std::mutex mtx;
public:
    CacheManager() {
        // Use Redis by default. If Redis is not available, switch to Memcached.
        try{
            cache = std::make_unique<RedisCache>();
        } catch(const std::exception& e){
            cache = std::make_unique<MemcachedCache>();
        }
    }

    void set(const std::string& key, const std::string& value, int expirationTime) {
        std::lock_guard<std::mutex> lock(mtx);
        cache->set(key, value, expirationTime);
    }

    std::string get(const std::string& key){
        std::lock_guard<std::mutex> lock(mtx);
        return cache->get(key);
    }
};
```

