```java
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.Jackson2JsonRedisSerializer;
import org.springframework.data.redis.serializer.StringRedisSerializer;

@SpringBootApplication
@EnableCaching
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }

    @Bean
    public RedisTemplate<?, ?> redisTemplate(RedisConnectionFactory factory){
        RedisTemplate<?, ?> template = new RedisTemplate<>();
        template.setConnectionFactory(factory);

        Jackson2JsonRedisSerializer jackson2JsonJsonRedisSerializer = new Jackson2JsonRedisSerializer(Object.class);

        ObjectMapper om = new ObjectMapper();
        om.setVisibility(PropertyAccessor.ALL, JsonAutoDetect.Visibility.ANY);
        om.enableDefaultTyping(ObjectMapper.DefaultTyping.NON_FINAL);
        jackson2JsonJsonRedisSerializer.setObjectMapper(om);

        template.setValueSerializer(jackson2JsonJsonRedisSerializer);//1
        template.setKeySerializer(new StringRedisSerializer()); //2
        template.afterPropertiesSet();

        return template;
    }
}
```
In this example, we set up a Spring Boot application with Redis caching. We're using the `@EnableCaching` annotation to enable the cache management and we define a bean for our redisTemplate which will be used to interact with Redis. This template is configured to use JSON serialization for both keys and values, allowing us to store any object type in Redis.
