int root(int i){ 
    while (parent[i] != i) { 
        parent[i] = parent[parent[i]];   // Path Compression
        i = parent[i]; 
    }
    return i; 
}
void union(int x, int y) { 
    int xroot = root(x); 
    int yroot = root(y); 
    if (rank[xroot] < rank[yroot]) parent[xroot] = yroot; 
    else if (rank[xroot] > rank[yroot]) parent[yroot] = xroot; 
    else { 
        parent[yroot] = xroot; 
        rank[xroot]++; 
    } 
} 
