```php
<?php
class ClinicUpdater {
    private $db; // Database connection object

    public function __construct($db) {
        $this->db = $db;
    }

    public function updateClinicStatus($clinicId, $status, $ipAddress){
        try{
            $this->db->beginTransaction(); // Start transaction

            // Fetch clinic details from DB
            $stmt = $this->db->prepare('SELECT * FROM clinics WHERE id = ? FOR UPDATE');
            $stmt->execute([$clinicId]);
            $result = $stmt->fetch(PDO::FETCH_ASSOC);

            // Update status, last modified IP address and last modified date in DB
            $updateStmt = $this->db->prepare('UPDATE clinics SET status = ?, ip_address = ?, updated_at = NOW() WHERE id = ?');
            $updateStmt->execute([$status, $ipAddress, $clinicId]);

            // Log status update operation
            $this->logStatusUpdate($result['user_id'], 'Clinic Status Updated', $clinicId);

            $this->db->commit(); // Commit transaction
        } catch (Exception $e) {
            $this->db->rollBack(); // Rollback in case of errors
            throw new Exception('Error updating clinic status: ' . $e->getMessage());
        }
    }

    private function logStatusUpdate($userId, $message, $clinicId) {
        // Implement logging here.
    }
}
?>
```
