  host: process.env.DB_HOST,
  dialect: 'mysql',
});

// Define your models and associations
const Supervisor = sequelize.define('supervisor', { name: Sequelize.STRING });
const Employee = sequelize.define('employee', { city: Sequelize.STRING, address: Sequelize.STRING });
Supervisor.hasMany(Employee);

app.get('/supervisors/:id', async (req, res) => {
  try {
    const supervisor = await Supervisor.findByPk(req.params.id, { include: [{ model: Employee }] });
    if (!supervisor) {
      return res.status(404).json({ error: 'Supervisor not found' });
    }
    logger.info(`Fetched supervisor details for ID ${req.params.id}`);
    res.json(supervisor);
  } catch (error) {
    logger.error('Error fetching supervisor details: ', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Start the server
