// Set up RabbitMQ connection and channel
amqp.connect('amqp://localhost', (err, conn) => {
  if (err) throw err;

  conn.createChannel((err, ch) => {
    if (err) throw err;

    const q = 'hello'; // Queue name

    ch.assertQueue(q, { durable: false });
    console.log(" [*] Waiting for messages in %s. To exit press CTRL+C", q);

    ch.consume(q, (msg) => {
      console.log(" [x] Received %s", msg.content.toString());

      // Create and save log to MongoDB
      let newLog = new Log({ 
        deviceId: 'Device ID',
        applicationName: 'Application Name',
        timestamp: Date.now(),
        severityLevel: 1,
      });

      newLog.save((err) => {
        if (err) console.log(err);
        else console.log('Saved log to MongoDB');
      });
    }, { noAck: true });
  });
});

// Set up Elasticsearch client
const esClient = new elasticsearch.Client({ node: 'http://localhost:9200' });

app.post('/api/log', (req, res) => {
  // Send log to RabbitMQ queue for processing
  amqp.connect('amqp://localhost', (err, conn) => {
    if (err) throw err;

    conn.createChannel((err, ch) => {
      if (err) throw err;

      const q = 'hello'; // Queue name
      let msg = JSON.stringify(req.body); // Convert to string for RabbitMQ 

      ch.assertQueue(q, { durable: false });
      ch.sendToQueue(q, Buffer.from(msg));
    });

    setTimeout(() => { conn.close(); }, 500); // Close connection after sending message
  });

  res.status(201).json({ status: 'Log received' });
});

// Start server
const port = 3000;
app.listen(port, () => console.log('Server started on port', port));
```

Please make sure to replace `localhost` with your actual RabbitMQ and Elasticsearch servers if not running locally. 

