    version: String,
}

pub struct ConfigurationManager {
    configs: HashMap<String, Config>,
    lock: RwLock<()>,
}

impl ConfigurationManager {
    pub fn new() -> Self {
        let mut config = HashMap::new();
        config.insert("0".to_string(), Config{version: "initial".to_string()});
