    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} Token;

Token validateAndProcessToken(char* apiURL, char* clientId, char* clientSecret) {
    // Initialize curl
    CURL *curl = curl_easy_init();

    if(curl) {
        CURLcode res;
        struct curl_slist *headers = NULL;

        // Set headers
        headers = curl_slist_append(headers, "Content-Type: application/json");
        headers = curl_slist_append(headers, "charset: utf-8");

        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Set url
        curl_easy_setopt(curl, CURLOPT_URL, apiURL);

        // Perform request and get response
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "Failed to perform request: %s\n", curl_easy_strerror(res));
            return (Token){NULL, -1, NULL, NULL};
        }

        // Parse response JSON into a json_t object
        json_error_t error;
        json_t *response = json_loads(curl_easy_strerror(res), 0, &error);

        if(!response) {
            fprintf(stderr, "Failed to parse response: %s\n", error.text);
            return (Token){NULL, -1, NULL, NULL};
        }

        // Extract required fields from the JSON object
        json_t *access_token = json_object_get(response, "access_token");
        json_t *expires_in = json_object_get(response, "expires_in");
        json_t *token_type = json_object_get(response, "token_type");
        json_t *refresh_token = json_object_get(response, "refresh_token");

        // Validate the fields and return if they're not valid
        if(!json_is_string(access_token) || !json_is_integer(expires_in) || 
            strcmp(json_string_value(token_type), "Bearer") != 0 || expires_in <= 0) {
                fprintf(stderr, "Invalid token response\n");
                return (Token){NULL, -1, NULL, NULL};
        }

        // Convert the fields into a Token struct and return
        return (Token){json_string_value(access_token), json_integer_value(expires_in), 
            json_string_value(token_type), json_is_string(refresh_token) ? json_string_value(refresh_token) : NULL};
    }
}
```
