import boto3  # AWS SDK for Python
from google.cloud import storage as gcs_storage  # Google Cloud Storage SDK
from azure.storage.blob import BlobServiceClient as AzureBlobStorage  # Azure Blob Storage SDK
from retry import retry  # Exponential backoff library
import threading  # For concurrency

class Uploader:
    def __init__(self, cloud_provider):
        self.cloud_provider = cloud_provider

        if cloud_provider == 'aws':
            self.client = boto3.client('s3')
        elif cloud_provider == 'gcp':
            self.client = gcs_storage.Client()
        elif cloud_provider == 'azure':
            self.client = AzureBlobStorage.from_connection_string(conn_str="my_connection_string")

    @retry((Exception), delay=1, backoff=2)  # Exponential backoff retry decorator
    def upload_file(self, file_name, bucket):
        if self.cloud_provider == 'aws':
            self.client.upload_file(file_name, bucket, file_name)
        elif self.cloud_provider == 'gcp':
            blob = self.client.blob(bucket)
            blob.upload_from_filename(filename=file_name)
        elif self.cloud_provider == 'azure':
            blob_client = self.client.get_blob_client(container=bucket, blob=file_name)
            with open(file_name, "rb") as data:
                blob_client.upload_blob(data)

    def upload_multiple_files(self, files):
        threads = []

        for file in files:
            thread = threading.Thread(target=self.upload_file, args=(*file,))  # Threads for concurrent uploads
            threads.append(thread)

        for thread in threads:
            thread.start()
