#include <stdio.h>
#include <pthread.h>
#include <stdatomic.h>
#include <unistd.h>

typedef struct {
    int type; //0 = integer, 1 = string, 2 = timestamp
    atomic_int data;
} DataObject;

void* processData(void *arg) {
    DataObject *obj = (DataObject *) arg;
    switch(obj->type){
        case 0: //integer processing
            printf("Processing integer: %d\n", obj->data);
            break;
        case 1: //string processing
            printf("Processing string: %s\n", (char*) &(obj->data));
            break;
        case 2: //timestamp processing
            printf("Processing timestamp: %ld\n", obj->data);
            break;
    }
    return NULL;
}

int main() {
    pthread_t threads[3];

    DataObject dataObjects[3] = {
        {0, 1}, //integer type with value 1
        {1, "Hello World"}, //string type with value "Hello World"
        {2, time(NULL)} //timestamp type with current time
    };

    for(int i = 0; i < 3; ++i) {
        pthread_create(&threads[i], NULL, processData, &dataObjects[i]);
    }

    for(int i = 0; i < 3; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
