import boto3  # AWS SDK for Python
from botocore.exceptions import BotoCoreError, NoCredentialsError
import requests
from requests_aws4auth import AWS4Auth

class CloudStorageLibrary:
    def __init__(self, access_key, secret_key):
        self.access_key = access_key
        self.secret_key = secret_key

        # Initialize S3 client and session
        self.session = boto3.Session(
            aws_access_key_id=self.access_key,
            aws_secret_access_key=self.secret_key
        )
        self.s3 = self.session.resource('s3')

    def upload_file(self, filepath, bucketname):
        try:
            self.s3.Bucket(bucketname).upload_file(Filename=filepath)
            print("File uploaded successfully.")
        except (NoCredentialsError, BotoCoreError) as e:
            print("Upload failed.", str(e))

    def download_file(self, filepath, bucketname):
        try:
            self.s3.Bucket(bucketname).download_file(Key=filepath)
            print("File downloaded successfully.")
        except (NoCredentialsError, BotoCoreError) as e:
            print("Download failed.", str(e))

    def list_files(self, bucketname):
        try:
            files = [obj.key for obj in self.s3.Bucket(bucketname).objects.all()]
            return files
        except (NoCredentialsError, BotoCoreError) as e:
            print("Listing failed.", str(e))

    def delete_file(self, filepath, bucketname):
        try:
            self.s3.Object(bucketname, filepath).delete()
            print("File deleted successfully.")
        except (NoCredentialsError, BotoCoreError) as e:
            print("Delete failed.", str(e))

    def restful_api_upload(self, url, filepath):
        try:
            auth = AWS4Auth(self.access_key, self.secret_key, 'us-east-1', 'execute-api')
            files = {'file': open(filepath, 'rb')}
            r = requests.post(url, files=files, auth=auth)
