void* do_work(void *arg) {
    thread_data *td = (thread_data*) arg;
    printf("Thread ID: %d\n", td->id);

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    thread_data tds[NUM_THREADS];
    int i;

    for(i=0; i<NUM_THREADS; ++i) {
        tds[i].id = i+1; // other initialization...

