#include <stdio.h>
#include <getopt.h>
#include <string.h>

struct ProgramOptions {
    char *directories;
    FILE *outputFile;
    int verbose;
};

void parse_options(int argc, char **argv, struct ProgramOptions *options) {
    static const struct option long_options[] = {
        {"directory", required_argument, 0, 'd'},
        {"output",    required_argument, 0, 'o'},
        {"verbose",   no_argument,       &(options->verbose), 1},
        {"help",      no_argument,       0, 'h'},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    int c = getopt_long(argc, argv, "d:o:vh", long_options, &option_index);

    while (c != -1) {
        switch (c) {
            case 'd':
                options->directories = optarg;
                break;
            case 'o':
                options->outputFile = fopen(optarg, "w");
                if (options->outputFile == NULL) {
                    printf("Failed to open output file: %s\n", optarg);
                    exit(EXIT_FAILURE);
                }
                break;
            case 'v':
                options->verbose = 1;
                break;
            case 'h':
                // Print usage information here.
                return;
        }
        c = getopt_long(argc, argv, "d:o:vh", long_options, &option_index);
    }
}

int main(int argc, char **argv) {
    struct ProgramOptions options = {".", NULL, 0};

    parse_options(argc, argv, &options);

    // Here is where your program would fetch and process configuration files from directories.
}
```
This code simply parses command-line options with the getopt_long() function and does nothing else for simplicity's sake. A real implementation of this program would be much larger, involving fetching files from remote sources, handling different compression types, handling API failures and rate limits, validating file paths, etc.
