Here's a very basic example of what the `convert_jpeg_to_pdf` function could look like in C:
```c
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>

int convert_jpeg_to_pdf(const char *input, const char *output) {
    FILE *pipe;
    int ret = 0;

    // Prepare the command
    char command[256];
    snprintf(command, sizeof(command), "convert %s %s", input, output);

    // Open pipe to file using ImageMagick's convert tool
    pipe = popen(command, "r");

    if (pipe == NULL) {
        syslog(LOG_ERR, "Failed to run command: %s", command);
        ret = 1;
    } else {
        // Close the pipe and check return status. 
        int exitCode = pclose(pipe);

        if (WIFEXITED(exitCode)) {
            int code = WEXITSTATUS(exitCode);

            if (code != 0) {
                syslog(LOG_ERR, "Command exited with non-zero status: %d", code);
                ret = 1;
            } else {
                syslog(LOG_INFO, "Successfully converted JPEG to PDF");
                ret = 0;
            }
        } else if (WIFSIGNALED(exitCode)) {
            int sig = WTERMSIG(exitCode);

            syslog(LOG_ERR, "Command exited due to signal: %d", sig);
            ret = 1;
        }
    }

    return ret;
}
```
This function is quite basic and does not cover many of the features you requested. For example, it assumes that ImageMagick's convert tool is installed and available on PATH. Also, error logging could be improved to include more details about what went wrong in a production environment. 

