```javascript
// Import necessary modules
const express = require('express');
const axios = require('axios');
const jwt = require('jsonwebtoken');

// Initialize Express application
const app = express();
app.use(express.json()); // Middleware for parsing JSON request bodies

// Authentication middleware using JWT
const authMiddleware = (req, res, next) => {
  const token = req.headers['authorization'];

  if (!token) return res.status(403).send('No token provided');

  jwt.verify(token, 'your-jwt-secret', function(err, decoded) {      
    if (err) return res.status(500).send({ auth: false, message: 'Failed to authenticate token' });    

    // If everything is good, save the req.user and pass on to next request handling middleware
    req.user = decoded.user;
    next();
  });
}

// Routes definition
app.get('/api/resource', authMiddleware, async (req, res) => {
  try {
    // Fetch data from the backend service using axios or other HTTP client library
    const response = await axios.get('http://backend-service-url');

    // Send the response to the frontend
    res.send(response.data);
  } catch (error) {
    console.log(error);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Start server
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server listening on port ${port}`));
```

