use std::process;
fn compile() -> i32 {
    let before = Instant::now();
    let mut hook = rustc_driver::SyncLazy::new(|| {});
    let process = process::Command::new("rustc").arg("--version").spawn().unwrap();
    let exit_code = process::Child::wait(process).unwrap().exit_status().as_nullable();

    if let Some(exit_code) = exit_code {
