['This is a complex task that requires the use of several different libraries and services which can be very extensive and time consuming to implement in one response. However, here's an outline of how you might approach designing such a system using Node.js, AWS S3 for cloud storage and processing images, DynamoDB for database storage, Express for creating REST API and more:

```javascript
const express = require('express');
const app = express();
const multer  = require('multer');
const upload = multer({ dest: 'uploads/' });
const AWS = require('aws-sdk');
const uuidv4 = require('uuid').v4;
AWS.config.update({region:'us-west-2'});
const s3 = new AWS.S3();
const ddb = new AWS.DynamoDB({apiVersion: '2012-08-10'});
const PORT = 3000;

app.post('/upload', upload.single('image'), async (req, res) => {
  const id = uuidv4();
  const params = {
    Bucket: 'myBucket', //replace with your bucket name
    Key: id + '.jpg', 
    Body: req.file.buffer,
    ContentType: req.file.mimetype
  };

  try{
    await s3.putObject(params).promise();

    const imageMetadata = { //extract EXIF data using a library like exif
      ID: id,
      URL: 'https://s3-us-west-2.amazonaws.com/'+ params.Bucket + '/' + params.Key, 
      ExifData : {} //replace with actual metadata
    };

    const item = {
      ID: {S: imageMetadata.ID},
      URL: {S: imageMetadata.URL},
      EXIF: {M: exifToDynamoFormat(imageMetadata.ExifData)} //convert Exif data to DynamoDB format
    };

    const dynamodbParams = {
      TableName: 'ImageMetaTable',
      Item: item
    }

    await ddb.putItem(dynamodbParams).promise();
    res.status(201).send({id: id});
  }catch(err){
    console.error(err);
    res.status(500).end();
  }
});

app.get('/images/:id', async (req, res) => {
  try{
    const dynamodbParams = {
      TableName: 'ImageMetaTable',
      Key: {"ID": {"S": req.params.id}}
    };

    const result = await ddb.getItem(dynamodbParams).promise();

    if(!result.Item){
      res.status(404).end();
    }else{
      const imageMetadata = {
        ID: result.Item.ID.S,
        URL: result.Item.URL.S,
        ExifData : dynamoFormatToExif(result.Item.EXIF.M) //convert from DynamoDB format to exif data 
      }
      res.send(imageMetadata);
    }
  }catch(err){
    console.error(err);
    res.status(500).end();
  }
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`)
});
```
Note that this is a simplified and minimalistic solution. Depending on the complexity of your use case, you may want to include:
