using UnityEngine;

public class RandomValueGenerator
{
    private float minVal;
    private float maxVal;

    public RandomValueGenerator(float min, float max)
    {
        this.minVal = min;
        this.maxVal = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(this.minVal, this.maxVal);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(Mathf.Ceil(this.minVal), Mathf.Floor(this.maxVal));
