  next();
});

// Setup retry mechanism for axios requests
retryAxios.attach();
axios.defaults.raxConfig = {
    instance: axios, // Axios instance to use for retries
    currentAttempt: 0, // The number of times the request has been attempted
    retry: Infinity, // Number of times to retry before failing
    noResponseRetries: 3, // Number of times to retry when it's a connection error
    httpMethodsToRetry: ['GET', 'HEAD'], // HTTP methods to automatically retry on
    statusCodesToRetry: [[100, 199], [429, 429]], // Status codes to automatically retry on
    backoffType: 'static', // Can be static or exponential; how much to delay before retrying the request
};

// Setup rate limiting
