class FileUploader {
public:
    FileUploader(const std::string& filename) : file_(filename, std::ios::binary), retry_count_(3), progress_(0) {}

    ~FileUploader() {
        if (upload_thread_.joinable()) {
            upload_thread_.join();
        }
    }

    void startUpload(const std::string& url, const std::string& apiKey) {
        upload_thread_ = std::thread(&FileUploader::doUpload, this, url, apiKey);
    }

    double getProgress() const {
        return progress_;
    }

private:
    void doUpload(const std::string& url, const std::string& apiKey) {
        curl_global_init(CURL_GLOBAL_ALL);
        CURL* curl = curl_easy_init();

        if (curl) {
            for (int retry = 0; retry < retry_count_; ++retry) {
                try {
                    std::string data = readFile();

                    // secure authentication using RSA with SHA-1 digest
                    unsigned char* encryptedData = rsaEncrypt(data, apiKey);

                    // encrypt the file content using AES 
                    unsigned char* aesData = aesEncrypt(encryptedData, apiKey);

                    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
                    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, reinterpret_cast<const char*>(&aesData));
                    curl_easy_perform(curl);

                    progress_ = 100;
                    break; // if successful, exit the loop
                } catch (std::exception& e) {
                    std::cerr << "Upload failed. Retrying...\n";
                    std::this_thread::sleep_for(std::chrono::seconds(1)); // delay before next retry
                }
            }

            curl_easy_cleanup(curl);
        }

        curl_global_cleanup();
    }

    std::string readFile() {
        file_.seekg(0, std::ios::end);
        size_t fileSize = file_.tellg();
        std::string buffer(fileSize, ' ');
        file_.seekg(0);
        file_.read(&buffer[0], fileSize);

        return buffer;
    }

    unsigned char* rsaEncrypt(const std::string& data, const std::string& apiKey) {
        // mock RSA encryption function, replace with actual implementation
        unsigned char* encryptedData = new unsigned char[data.size()];

        for (int i = 0; i < data.size(); ++i) {
            encryptedData[i] = static_cast<unsigned char>(data[i]) ^ apiKey[i % apiKey.size()];
        }

        return encryptedData;
    }

    unsigned char* aesEncrypt(const std::string& data, const std::string& apiKey) {
        AES_KEY encKey;

        // mock AES encryption function, replace with actual implementation
        unsigned char* encryptedData = new unsigned char[data.size()];
        memcpy(encryptedData, data.c_str(), data.size());

        return encryptedData;
    }

    std::ifstream file_;
    const int retry_count_;
    std::atomic<double> progress_;
    std::thread upload_thread_;
};
```

