// Event Storage
typedef struct {
    pthread_mutex_t mutex;
    int size;
    TrafficEvent** events;
} EventStorage;

void initStorage(EventStorage* storage) {
    pthread_mutex_init(&storage->mutex, NULL);
    storage->size = 0;
    storage->events = malloc(sizeof(TrafficEvent*));
}

// Function to store an event
void storeEvent(EventStorage* storage, TrafficEvent* event) {
    pthread_mutex_lock(&storage->mutex);
    ++storage->size;
    storage->events = realloc(storage->events, sizeof(TrafficEvent*) * storage->size);
    storage->events[storage->size - 1] = event;
    pthread_mutex_unlock(&storage->mutex);
}

// Function to retrieve an event
TrafficEvent* getEvent(EventStorage* storage, int index) {
    pthread_mutex_lock(&storage->mutex);
    TrafficEvent* event = NULL;
    if (index < storage->size && index >= 0) {
        event = storage->events[index];
    }
    pthread_mutex_unlock(&storage->mutex);
    return event;
}

