['```python
import logging
import boto3
from google.cloud import storage
from azure.storage.blob import BlobServiceClient
from retrying import retry

class StorageConnector:
    def __init__(self, service_type):
        self.service = None
        if service_type == "AWS":
            self.service = boto3.client('s3')
        elif service_type == "GCP":
            self.service = storage.Client()
        elif service_type == "Azure":
            self.service = BlobServiceClient.from_connection_string(conn_str="my_connection_string")
        else:
            raise ValueError("Invalid storage type")

    @retry(wait_exponential_multiplier=1000, wait_exponential_max=10000)
    def upload_file(self, file_name, bucket):
        try:
            self.service.upload_file(file_name, bucket)
        except Exception as e:
            logging.error("Error while uploading file to storage: %s", str(e))
            raise StorageException('Upload failed') from e

class MicroService:
    def __init__(self, config):
        self.config = config
        self.storage_connector = StorageConnector(config['service'])

    def process_data(self, data):
        try:
            # Data processing logic goes here
            return processed_data
        except Exception as e:
            logging.error("Error while processing data: %s", str(e))
            raise ProcessingException('Processing failed') from e

    def run(self):
        data = self.load_data()
        processed_data = self.process_data(data)
        self.storage_connector.upload_file(processed_data, self.config['bucket'])
```

