import java.io.*;
import java.util.concurrent.*;

public class SerializedDeserializerService {

    private ExecutorService executor = Executors.newFixedThreadPool(10);

    public Future<Object> deserializeAsync(byte[] serialized) {
        return executor.submit(() -> deserialize(serialized));
    }

    private Object deserialize(byte[] serialized) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(serialized); 
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new DeserializationException("Failed to deserialize object", e);
        }
    }
}
```
