        this.min_value = min_value;
        this.max_value = max_value;
    }

    public float GenerateFloat() {
        return (float)(new System.Random().NextDouble()) * (max_value - min_value) + min_value;
    }

    public int GenerateInt() {
        return new System.Random().Next(min_value, max_value);
