#include <stdio.h>
#include <pthread.h>
#include <curl/curl.h>
#include <dirent.h>

// Function to fetch data from remote API
size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s) {
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

void fetchFromAPI() {
  CURL *curl;
  CURLcode res;

  curl = curl_easy_init();
  if(curl) {
    struct string s;
    s.len = 0;
    s.ptr = malloc(s.len+1);
    if(s.ptr == NULL) {
      fprintf(stderr, "malloc() failed\n");
      exit(EXIT_FAILURE);
    }

    curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/data");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

    res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
      fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
      printf("%s\n", s.ptr);
    }

    free(s.ptr);
    curl_easy_cleanup(curl);
  }
}

// Function to read local files in a directory
void processDirectory() {
  DIR *d;
  struct dirent *dir;
  d = opendir(".");
  if (d) {
    while ((dir = readdir(d)) != NULL) {
      printf("%s\n", dir->d_name);
    }
    closedir(d);
  }
}

int main() {
  pthread_t thread1, thread2;

  // Create two threads - one for fetching from API and another for processing local directory
  if (pthread_create(&thread1, NULL, fetchFromAPI, NULL) != 0) {
    perror("Failed to create the thread");
    return 1;
  }

  if (pthread_create(&thread2, NULL, processDirectory, NULL) != 0) {
    perror("Failed to create the thread");
    return 1;
  }

  // Wait for both threads to finish
  pthread_join(thread1, NULL);
  pthread_join(thread2, NULL);

  return 0;
}
```
