['Here's a simplified version of how you could implement such a logging framework from scratch in C++. 

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <unordered_map>
using namespace std;

class UnionFind {
    unordered_map<int, int> parent;
public:
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unionSet(int x, int y) {
        int px = find(x), py = find(y);
        if (px != py) 
            parent[py] = px;
    }
};

int countDisjointPairs(vector<int>& nums) {
    UnionFind uf;
    int disjointCount = 0;
    auto startTime = chrono::high_resolution_clock::now();

    for (auto n : nums) 
        uf.unionSet(n, n);

    for (int i = 0; i < nums.size(); ++i) {
        for (int j = i + 1; j < nums.size(); ++j) {
            if (uf.find(nums[i]) != uf.find(nums[j])) 
                disjointCount++;

            auto endTime = chrono::high_resolution_clock::now();
            cout << "For pair (" << nums[i] << ", " << nums[j] << "): ";
            cout << chrono::duration<double, milli>(endTime - startTime).count() 
                 << " ms\n";
        }
    }

    return disjointCount;
}
```
This code first declares a class UnionFind to implement the Union-Find data structure. The find and unionSet methods are defined inside this class. Then, the countDisjointPairs function is implemented. It takes an array of integers as input and returns the number of disjoint pairs in it using a Union-Find data structure. For every pair of elements in the array, it checks if they belong to different sets in the Union-Find data structure and increments the disjointCount if they do not. It also measures the time taken for each pair by recording the start and end times using the high_resolution_clock from the chrono library.
']

