        IInventoryService inventoryService, 
        IShippingService shippingService, 
        ILogger<OrderProcessor> logger)
    {
        _paymentService = paymentService;
        _inventoryService = inventoryService;
        _shippingService = shippingService;
        _logger = logger;
    }

    public async Task HandleOrderRequestAsync(Order order, CancellationToken cancellationToken)
    {
        try
        {
            // Validate and sanitize inputs here...

            var inventoryResult = await _inventoryService.CheckInventory(order);

            if (inventoryResult.IsSuccessful)
            {
                var paymentResult = await _paymentService.ProcessPayment(order);

                if (paymentResult.IsSuccessful)
                {
                    var shippingResult = await _shippingService.ShipOrder(order);

                    // Further processing...
                }
            }
        }
