#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>

typedef struct session_t {
    pthread_mutex_t mutex;
    sem_t resourceSem;
    atomic_int state;
    void* data;
} session_t;

session_t* createSession() {
    session_t* s = malloc(sizeof(session_t));
    pthread_mutex_init(&s->mutex, NULL);
    sem_init(&s->resourceSem, 0, 1);
    atomic_store(&s->state, IDLE);
    return s;
}

void useSession(session_t* session) {
    pthread_mutex_lock(&session->mutex);
    sem_wait(&session->resourceSem);
    // Use the session here.
    sem_post(&session->resourceSem);
    pthread_mutex_unlock(&session->mutex);
}

void destroySession(session_t* session) {
    sem_destroy(&session->resourceSem);
    pthread_mutex_destroy(&session->mutex);
    free(session);
}
```

This code defines a struct for a session that includes a mutex for thread synchronization, a semaphore for resource management and an atomic integer to represent the state of the session. It also provides functions to create, use and destroy sessions. 

