['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <netinet/in.h> // for struct in_addr

typedef enum {
    EVENT_TYPE1,
    EVENT_TYPE2,
    /* Additional event types here */
} EventType;

struct NetworkDeviceEvent {
    time_t timestamp;
    EventType type;
    struct in_addr sourceIP;
    struct in_addr destinationIP;
    size_t packetSize;
    unsigned long long uniqueID;
};

/* Define your global variables here */
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
struct NetworkDeviceEvent *eventPool = NULL;
size_t eventCount = 0, eventCapacity = 0;

void addEvent(const struct NetworkDeviceEvent *newEvent) {
    pthread_mutex_lock(&lock);
    if (eventCount == eventCapacity) {
        eventCapacity = eventCapacity ? eventCapacity*2 : 1;
        eventPool = realloc(eventPool, eventCapacity * sizeof(*eventPool));
        memset(eventPool + eventCount, 0, (eventCapacity - eventCount) * sizeof(*eventPool));
    }
    memcpy(&eventPool[eventCount++], newEvent, sizeof(*newEvent));
    pthread_mutex_unlock(&lock);
}

struct NetworkDeviceEvent *getEvent(unsigned long long uniqueID) {
    struct NetworkDeviceEvent *result = NULL;
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < eventCount; ++i) {
        if (eventPool[i].uniqueID == uniqueID) {
            result = &eventPool[i];
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return result;
}

void updateEvent(const struct NetworkDeviceEvent *updatedEvent) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < eventCount; ++i) {
        if (eventPool[i].uniqueID == updatedEvent->uniqueID) {
            memcpy(&eventPool[i], updatedEvent, sizeof(*updatedEvent));
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void deleteEvent(unsigned long long uniqueID) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < eventCount; ++i) {
        if (eventPool[i].uniqueID == uniqueID) {
            memmove(&eventPool[i], &eventPool[i+1], sizeof(*eventPool) * (eventCount - i - 1));
            --eventCount;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}
```
']

