public static XElement FindFirstByName(XDocument doc, string name)
{
    var elements = doc.Descendants().Where(e => e.Name.LocalName == name);

    if (!elements.Any())
        throw new Exception("No element found with the given name");
    else if (elements.Count() > 1)
        throw new Exception("Multiple elements found with the same name");
    else 
        return elements.First();
