std::list<NFAPI_CRC_INDICATION_PDU_T*> list;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *updateList(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T* newElement = (NFAPI_CRC_INDICATION_PDU_T*) arg;

    pthread_mutex_lock(&mutex);
    if (list.size() >= MAX_ELEMENTS) {
        NFAPI_CRC_INDICATION_PDU_T* oldestElement = list.front();
        delete oldestElement; // free the memory
        list.pop_front();     // remove from the list
    }
    list.push_back(newElement);
    pthread_mutex_unlock(&mutex);
}

void clearList() {
    pthread_mutex_lock(&mutex);
    for (NFAPI_CRC_INDICATION_PDU_T* element : list) {
        delete element; // free the memory
    }
    list.clear();
    pthread_mutex_unlock(&mutex);
}
``` 

