typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Add fields relevant to your use case
} NFAPI_CRC_INDICATION_PDU_T;

// Create a Node structure for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety
Node *head = NULL;
int count = 0;

// Function to add an element at the beginning of the list
void addElement(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutex);  // Acquire lock before accessing shared data

    Node* newNode = (Node*)malloc(sizeof(Node));
    assert(newNode != NULL);

    newNode->data = data;
    newNode->next = head;
    head = newNode;
    count++;

    // If list is full, discard the last element
    if (count > 50000) {
        Node* current = head;
        while(current->next->next != NULL){
            current = current->next;
        }
        free(current->next);
        current->next = NULL;
        count--;
    }

    pthread_mutex_unlock(&mutex);  // Release lock after modifying shared data
}
```

