#include <thread>
#include <system_error>

namespace fs = std::filesystem;

bool isWebConfigPresent(const fs::path& path) {
    return fs::exists(path / "web.config");
}

void addWebsiteToDirectoryAndStartIt(const fs::path& dirPath, const std::string& websiteURL) {
    // Check if the directory exists
    if (!fs::is_directory(dirPath)) {
        throw std::runtime_error("The provided path is not a directory");
    }

    // Create a new thread to start the website
    std::thread webServerThread([&]() {
        fs::path fullWebsiteURL = dirPath / websiteURL;

        // Check if 'web.config' file exists in the path, throw exception otherwise
        if (!isWebConfigPresent(fullWebsiteURL)) {
            throw std::runtime_error("No web.config found in directory");
        }

        // Start website using system command here
        // This is a placeholder and won't work as it will depend on your server type, 
        // for example, Apache or Nginx. You may want to use their respective APIs 
        // rather than calling system commands.
        std::system(("start_webserver " + fullWebsiteURL.string()).c_str());
    });

    // Detach from the thread so it can run independently of the main program
    webServerThread.detach();
}
``` 
This is a very basic example and does not cover every detail that you've asked for in your question, but it should give you a good starting point on how to structure such functionality using C++ `std::thread` and `system` functionalities. Remember, creating a comprehensive library as described in the problem statement will require much more advanced programming techniques and considerations than can be covered here. You might want to consider hiring professional developers or software engineers for this task.
