1. In C:
```c
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

sem_t activeSessions;

void handleSession(int sessionId) {
    sem_wait(&activeSessions); // Wait for a slot to be available
    printf("Handling session %d\n", sessionId);
    sleep(10); // Simulate session handling
    printf("Finished session %d\n", sessionId);
    sem_post(&activeSessions); // Free up a slot when done
}

void* handleSessionThreaded(void *arg) {
    int id = *((int*) arg);
    handleSession(id);
    return NULL;
}

#define M 10 // Maximum concurrent sessions

int main() {
    sem_init(&activeSessions, 0, M); // Initialize semaphore with maximum active sessions set to M
    pthread_t threads[2*M]; // Simulate two groups of M concurrent users

    for(int i = 0; i < 2 * M; ++i) {
        int *id = malloc(sizeof(*id)); 
        *id = i;
        pthread_create(&threads[i], NULL, handleSessionThreaded, id); // Create a new thread for each user
    }

    for(int i = 0; i < 2*M; ++i) {
        pthread_join(threads[i], NULL); 
    }

    return 0;
}
```
This C code employs a semaphore to limit the number of active sessions, simulating M users each handling an independent session. This is a basic example and does not include real-time event streams from cloud-native sources, authentication, logging framework, or backpressure strategies for handling data spikes.

