```csharp
public async Task<string> GetContentFromCms(int pageId, int elementId)
{
    for (var i = 0; i < MAX_RETRIES; i++)
    {
        try
        {
            return await _cmsClient.GetElementAsync(pageId, elementId);
        }
        catch when (i != MAX_RETRIES - 1) // Retry only if we have attempts left
        {
            var delay = Math.Pow(2, i) * 1000; // Exponential backoff

            await Task.Delay((int)delay);
        }
    }

    throw new Exception("Failed to get content from CMS after retries.");
}
