public class MyExceptionHandlerMiddleware {
    private readonly RequestDelegate _next;
    private readonly ILogger<MyExceptionHandlerMiddleware> _logger;

    public MyExceptionHandlerMiddleware(RequestDelegate next, ILogger<MyExceptionHandlerMiddleware> logger) {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext httpContext) {
        try {
            await _next(httpContext);
        } catch (Exception ex) when (LogAndHandle(ex)) {}
    }

    private bool LogAndHandle(Exception ex) {
        _logger.LogError($"{DateTime.Now}, An error has occurred: {ex}");

        // Depending on your strategy, you might choose to handle the exception here.
        // For example, returning a specific HTTP status code or redirecting the user
    }
}
```
