typedef struct {
    int* data; // assuming integer data for simplicity, in reality it can be any type of data object
    sem_t lock;
} buffer_item;

#define BUFFER_SIZE 10
buffer_item buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t empty, full;

void init() {
    sem_init(&empty, 0, BUFFER_SIZE);
    sem_init(&full, 0, 0);
}

// producer thread function
void* producer(void* arg) {
    int item = *((int*)arg); // assuming data is an integer for simplicity
    buffer_item* b = &buffer[head];
    sem_wait(&empty);
    pthread_mutex_lock(&mutex);

    printf("Producing: %d\n", item);
    b->data = &item; // here you'd actually assign real data to buffer item
    head = (head + 1) % BUFFER_SIZE;

    pthread_mutex_unlock(&mutex);
    sem_post(&full);
}

// consumer thread function
void* consumer(void* arg) {
    int* item;
    buffer_item* b = &buffer[tail];
    sem_wait(&full);
    pthread_mutex_lock(&mutex);

    item = b->data; // here you'd actually get real data from buffer item
    printf("Consuming: %d\n", *item);
    tail = (tail + 1) % BUFFER_SIZE;

    pthread_mutex_unlock(&mutex);
    sem_post(&empty);
}
```
This is a basic producer-consumer model, with the buffer being an array of `buffer_item` structs. The `producer` function puts data into the buffer and the `consumer` function reads from it. 

