    {
        _logger = logger;
    }

    public async Task<List<string>> GetSupportedHashFunctions() 
    {
        try 
        {
            var response = await _client.GetAsync("https://example.com/api/supported-hash-functions");

            if (response.IsSuccessStatusCode) 
            {
                dynamic data = JObject.Parse(await response.Content.ReadAsStringAsync());
                return ((JArray)data["hashes"]).ToObject<List<string>>();
            } 
            else 
            {
                _logger.LogError("Failed to get supported hash functions");
                throw new Exception("Failed to get supported hash functions");
            }
        } 
        catch (Exception e) 
        {
            _logger.LogError(e, "Error while getting supported hash functions");
            throw;
        }
    }

    public string GenerateHash(string input, string algorithm) 
    {
        using var hashAlgorithm = HashAlgorithm.Create(algorithm);

        if (hashAlgorithm == null) 
        {
            _logger.LogError("Unsupported hash algorithm: {0}", algorithm);
            throw new Exception("Unsupported hash algorithm");
        }

        var inputBytes = System.Text.Encoding.UTF8.GetBytes(input);
        var hashBytes = hashAlgorithm.ComputeHash(inputBytes);

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    public bool ValidateHash(string input, string expected, string algorithm) 
    {
        var actual = GenerateHash(input, algorithm);
        return actual == expected;
    }
