        mtx.lock();

        // Get data chunk from the source
        auto chunk = source.getDataChunk();

        // Asynchronously process the data chunk
        std::future<void> future = std::async(std::launch::async, [chunk, &source] { 
            processDataChunk(chunk, source); 
