typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU;

typedef struct PduStreamProcessor {
    pthread_mutex_t lock;
    int maxBufferSize;
    NFAPI_CRC_INDICATION_PDU* buffer;
    int bufferHead;
    int bufferTail;
} PduStreamProcessor;

void initProcessor(PduStreamProcessor* processor, int maxPDUs) {
    pthread_mutex_init(&processor->lock, NULL);
    processor->maxBufferSize = maxPDUs;
    processor->bufferHead = 0;
    processor->bufferTail = 0;
    processor->buffer = malloc(sizeof(NFAPI_CRC_INDICATION_PDU) * maxPDUs);
}

void addToBuffer(PduStreamProcessor* processor, NFAPI_CRC_INDICATION_PDU pdu) {
    if (processor == NULL || processor->buffer == NULL) {
        printf("Invalid stream processor or buffer!\n");
        return;
    }

    pthread_mutex_lock(&processor->lock);
    // Ensure there is room in the buffer for another PDU
    if ((processor->bufferTail + 1) % processor->maxBufferSize != processor->bufferHead) {
        processor->buffer[processor->bufferTail] = pdu;
        processor->bufferTail = (processor->bufferTail + 1) % processor->maxBufferSize;
    } else {
        printf("Buffer full, dropping PDU!\n");
    }
    pthread_mutex_unlock(&processor->lock);
}

NFAPI_CRC_INDICATION_PDU getFromBuffer(PduStreamProcessor* processor) {
    NFAPI_CRC_INDICATION_PDU pdu = {}; // Initialize with empty PDU data

    if (processor == NULL || processor->buffer == NULL) {
        printf("Invalid stream processor or buffer!\n");
        return pdu;
    }

    pthread_mutex_lock(&processor->lock);
    // Check if there are PDUs in the buffer to process
    if (processor->bufferHead != processor->bufferTail) {
        pdu = processor->buffer[processor->bufferHead];
        processor->bufferHead = (processor->bufferHead + 1) % processor->maxBufferSize;
    } else {
        printf("No PDUs in buffer to process!\n");
    }
    pthread_mutex_unlock(&processor->lock);

    return pdu;
}
```

This code is a starting point. You would need to add more functionality for reading from and writing into the hardware interface, handling configuration parameters, implementing batch processing, load balancing among multiple nodes, testing cases etc. Also, there might be performance issues with locking mechanism in multi-threaded environment if not managed properly. This code will also need to be adjusted based on specifics of your 5G baseband hardware.
