class LteDlGrantRequest {
public:
    int cellID;
    int bwpID;
    int slotIndex;
    double powerLevel;
    int QoSPriority;
};

std::mutex mtx;  // Mutex for thread safety
std::atomic<bool> shutdown(false); // Flag to signal shutdown
std::condition_variable cv; // Condition variable for synchronization
std::vector<LteDlGrantRequest> requestQueue; // Queue to hold requests

// Function to add a new DL Grant Request
void AddDLGrantRequest(const LteDlGrantRequest& req) {
    std::lock_guard<std::mutex> lock(mtx); // Lock the mutex before adding request
    requestQueue.push_back(req); 
}

// Exponential backoff for API calls
int BackOffTime() {
    static thread_local int attempts = 0;
    ++attempts;
    std::uniform_int_distribution<int> distribution(0, (1 << attempts) - 1);
    std::default_random_engine generator;
    return distribution(generator);
}

// Worker thread function to handle DL Grant Requests
void HandleDLGrantRequest() {
    while(!shutdown){ // Loop until we are shutdown
        LteDlGrantRequest req;
        bool workToDo = false; 
        {
            std::lock_guard<std::mutex> lock(mtx); // Lock the mutex before checking queue
            if (!requestQueue.empty()) { 
                req = requestQueue.back(); 
                requestQueue.pop_back(); 
                workToDo = true;
            }
        }
        if (workToDo) {
            bool success = false;
            int attempts = 0;
            while(!success && !shutdown){ // Retry until we succeed or shutdown
                try{
                    // Call API here, using req fields as parameters
                    ++attempts;
                    if(attempts > 5) { // If we've failed 5 times, give up and move on to next request
                        break;
                    }
                    int backoff = BackOffTime();
                    std::this_thread::sleep_for(std::chrono::milliseconds(backoff));
                } catch (const std::exception& e) { // Catch any API call exceptions
                    ++attempts;
                }
            }
        } else {
            std::unique_lock<std::mutex> lock(mtx); 
            cv.wait(lock); // Wait for a signal when we have work to do or shutdown if queue is empty
        }
    }
}
```
