#include "LOGICAL_CONNECTION_RECORD"  // This should be replaced with the actual third-party API header.

class BatchProcessor {
public:
    BatchProcessor(int maxBufferSize) : maxBufferSize_(maxBufferSize), running_(true) {
        workerThread_ = std::thread(&BatchProcessor::ProcessLoop, this);
    }
    ~BatchProcessor() {
        Stop();
    }

    void PushRecord(const LOGICAL_CONNECTION_RECORD& record) {
        std::unique_lock<std::mutex> lock(mtx_);
        if (buffer_.size() >= maxBufferSize_) {
            buffer_.pop();  // Remove the oldest record.
        }
        buffer_.push(record);
        lock.unlock();
        cv_.notify_all();
    }

private:
    void ProcessLoop() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mtx_);
            cv_.wait(lock, [this](){ return !buffer_.empty() || !running_; });
            if (!running_) break;

            // Process records here.
            while(!buffer_.empty()) {
                LOGICAL_CONNECTION_RECORD record = buffer_.front();
                buffer_.pop();

                lock.unlock();
                // Simulate processing time.
                std::this_thread::sleep_for(std::chrono::milliseconds(1));  
                lock.lock();
            }
        }
    }

    void Stop() {
        running_ = false;
        cv_.notify_all();
        if (workerThread_.joinable()) workerThread_.join();
    }

private:
    std::thread workerThread_;
    std::mutex mtx_;
    std::condition_variable cv_;
    bool running_;
    int maxBufferSize_;
    std::queue<LOGICAL_CONNECTION_RECORD> buffer_;  // This is a basic implementation and should be replaced with an efficient data structure.
};
