    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pduArray == NULL) {
        logError("Failed to allocate memory");
        return NULL; // Insufficient memory error
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < n; ++i) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand();
        pduArray[i].RNTI = rand();
        pduArray[i].CRC_INDICATION_REL8_TAG = rand();

        // Randomly set CRCFLAG between 0 and 1
        pduArray[i].CRCFLAG = rand() % 2;
    }

    if (!saveToDatabase(pduArray, n)) {
