```c++
#include <sys/types.h>
#include <unistd.h>
#include <stdarg.h>
#include <ctime>
#include <string>
#include <fstream>
#include <mutex>
#include <sys/resource.h>

// A simple configuration class
class Config {
public:
    static bool loggingEnabled() { 
        // Read from config file or environment variable
        return true; 
    }

    static int getLogLevel() { 
        // Read from config file or environment variable
        return 2; 
    }
};

class Logger {
public:
    void logErrorWithMetrics(std::string level, const char* fmt...) {
        if(!Config::loggingEnabled()) return;

        int currentLogLevel = Config::getLogLevel();
        if (level == "error" && currentLogLevel < 1) return;
        else if (level == "warning" && currentLogLevel < 2) return;
        else if (currentLogLevel < 3);

        std::lock_guard<std::mutex> lock(logMutex_);

        va_list args;
        va_start(args, fmt);

        time_t now = time(0);
        char* dt = ctime(&now);

        struct rusage usage;
        getrusage(RUSAGE_SELF, &usage);

        std::ofstream logFile("application.log", std::ios_base::app | std::ios_base::out);
        logFile << dt << " PID: " << getpid() 
                << " CPU Usage: user - " << usage.ru_utime.tv_usec
                << ", system - "<< usage.ru_stime.tv_usec;

        while (*fmt != '\0') {
            if (*fmt == 'd') {
                int i = va_arg(args, int);
                logFile << i << " ";
            } else if (*fmt == 'c') {
                // assuming the 'char' is the next argument
                int c = va_arg(args, int);
                logFile << static_cast<char>(c) << " ";
            }
            ++fmt;
        }

        va_end(args);
    }

private:
    std::mutex logMutex_;
};
```
Configuration for this logger can be controlled via a configuration file or environment variables as shown in the `Config` class. The logging level is set to 1 (error only), 2 (warning and error) or 3 (info, warning, error). You may modify these values according to your needs.

