For this particular request, we will focus on designing RESTful APIs using Node.js with Express, implementing rate limiting middleware, and managing JWT tokens for user authentication. We will also include error handling and basic logging setup. However, please note that this is a simplified version of your complex requirement and does not cover all the aspects you mentioned in depth. 

```javascript
const express = require('express');
const rateLimit = require("express-rate-limit");
const jwt = require('jsonwebtoken');
const app = express();
app.use(express.json());

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Middleware for checking JWT token
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization']
  const token = authHeader && authHeader.split(' ')[1]

  if (token == null) return res.sendStatus(401)

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    console.log(err)
    if (err) return res.sendStatus(403)
    req.user = user
    next()
  })
}

// Sample route for authentication and rate limiting middleware check
app.get('/api/data', authenticateToken, (req, res) => {
  // Fetch and return data here...
})

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!!');
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Listening on port ${port}...`));
```

In this example, we use express-rate-limit for API rate limiting to prevent potential DDoS attacks and to manage spikes in request rates. We're also implementing a middleware function that checks the JWT token sent with each request to secure our APIs. Finally, we add a basic error handling middleware to deal with any unexpected errors in our application. 

