public class TopIntegersService {
    private static final Logger logger = LogManager.getLogger(TopIntegersService.class);

    // A priority queue to store the top integers
    private PriorityQueue<Integer> topInts; 
    // Lock for concurrent modification of the queue
    private ReentrantLock lock = new ReentrantLock();

    public TopIntegersService() {
        topInts = new PriorityQueue<>((a, b) -> Integer.compare(b, a));
    }

    // Method for ingesting data
    public void ingestData(int value) {
        lock.lock();
        try {
            if (topInts.size() < 10000 || topInts.peek() > value) {
                topInts.offer(value);
            }

            // If the queue size exceeds 10,000, remove the smallest element
            if (topInts.size() > 10000) {
                topInts.poll();
            }
        } finally {
            lock.unlock();
        }
    }

