public class DataCache {
    private static final int MAXIMUM_CACHE_SIZE = 100;
    private LRUMap<String, Object> cache = new LRUMap<>(MAXIMUM_CACHE_SIZE);

    public Object getDataFromCache(String key) {
        return cache.get(key);
    }

    public void addToCache(String key, Object data) {
        if (cache.size() < MAXIMUM_CACHE_SIZE) {
            cache.put(key, data);
        } else {
            cache.remove(cache.keySet().iterator().next());
            cache.put(key, data);
        }
