```cpp
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include <dlfcn.h>
#include <mutex>
#include <shared_mutex>
#include <future>

namespace fs = std::filesystem;
using namespace std::chrono_literals;

class Library {
    void* handle_;
    std::function<void()> function_;
public:
    Library(const fs::path& path) : handle_(dlopen(path.c_str(), RTLD_LAZY)) {}
    ~Library() { dlclose(handle_); }

    void* symbol(const std::string& name) const { return dlsym(handle_, name.c_str()); }
};

class FileHandler {
    std::mutex mtx_;
    std::vector<std::future<std::string>> futures_;
public:
    ~FileHandler() { for (auto& f : futures_) if (f.valid()) f.wait(); }

    void async_read(const fs::path& path) {
        auto future = std::async([this, &path] {
            std::lock_guard<std::mutex> lock(mtx_);

            // Simulate network latency
            std::this_thread::sleep_for(1s);

            if (!fs::exists(path)) throw std::runtime_error("File not found");

            std::ifstream file{path};
            return std::string{(std::istreambuf_iterator<char>(file)), (std::istreambuf_iterator<char>())};
        });

        futures_.push_back(std::move(future));
    }
};
```
In this code:
1. The `Library` class represents a shared library and allows you to load, use and unload it dynamically at runtime.
2. The `FileHandler` class asynchronously reads files from disk using C++'s std::async for concurrent file reading. It uses a shared mutex to allow multiple threads to read the same file simultaneously while preventing them all writing to the same file concurrently. 

This is very simplified and does not include error handling, logging or other requirements that would be required in a production application. In real-world scenario, it's likely you would use C++ libraries like Boost for more advanced features, Google Test or doctest for testing, and spdlog or Glog for logging. 

