3. Hashing Mechanism with Rate Limiter (using `SemaphoreSlim`)

```csharp
public class HashService { 
    private SemaphoreSlim semaphore = new SemaphoreSlim(1, 1); // max concurrency of 1

    public async Task<byte[]> ComputeHashAsync(Stream stream) { 
        await semaphore.WaitAsync();

        try { 
            var hashAlgorithm = SHA256.Create();

            return await hashAlgorithm.ComputeHashAsync(stream);
        } finally { 
            semaphore.Release();
        }
    }
}
```

4. JavaScript DOM processing (using `MutationObserver` for updates)

```javascript
function processDomTree(rootElement, callback) { 
    // ... apply function to root element and its descendants...

    var observer = new MutationObserver(mutations => { 
        mutations.forEach(m => { 
            if (m.type === 'childList') {
                m.addedNodes.forEach(node => processDomTree(node, callback));
            } else if (m.type === 'attributes' || m.type === 'characterData') {
                callback(m.target);
            }
        });
    });

    observer.observe(rootElement, {childList: true, attributes: true, characterData: true});
}
```

