['Here's an example code snippet which implements some of these features using C++ libraries such as libcurl for HTTP requests, nlohmann/json for JSON parsing, Boost.Asio for async operations, and Boost.Program_options for command line options. Note that this is a simplified version, actual implementation would involve handling many edge cases and error scenarios, like reconnection to services in case of disconnection etc:

```cpp
#include <iostream>
#include <string>
#include <boost/asio.hpp>
#include <nlohmann/json.hpp>
#include <libcurl/curl.h>
#include <boost/program_options.hpp>
namespace po = boost::program_options;

struct ServerConfig {
    std::string url;
    int interval;
};

class MonitoringApp {
public:
    MonitoringApp(std::vector<ServerConfig> configs, int cooldownPeriod) 
        : ioService(), timer(ioService), configs(configs), cooldownPeriod(cooldownPeriod), randomDevice(), mtGen(randomDevice()) {}

    void Start() {
        ScheduleNextCheck();
        ioService.run();
    }

private:
    boost::asio::io_service ioService;
    boost::asio::steady_timer timer;
    std::vector<ServerConfig> configs;
    int cooldownPeriod;

    std::random_device randomDevice;
    std::mt19937 mtGen;

    void ScheduleNextCheck() {
        auto& next = configs[mtGen() % configs.size()];

        timer.expires_from_now(boost::asio::chrono::seconds(next.interval));
        timer.async_wait([this, &next](const boost::system::error_code&){
            CheckServerStatus(next);
            ScheduleNextCheck();
        });
    }

    void CheckServerStatus(const ServerConfig& config) {
        // Use libcurl to make HTTP request here
        CURL *curl = curl_easy_init();
        if (curl) {
            CURLcode res;
            curl_easy_setopt(curl, CURLOPT_URL, config.url.c_str());
            res = curl_easy_perform(curl);

            // Handle response here...

            curl_easy_cleanup(curl);  
        }
    }
};

int main(int argc, char** argv) {
    std::string configPath;
    int interval = 10;  // Default value

    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "produce help message")
        ("i,interval", po::value<int>(), "set interval")
        ("f,file", po::value<std::string>(&configPath), "configuration file path")
    ;

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);  

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 1;
    }

    if (vm.count("interval")) {
        interval = vm["interval"].as<int>();
    }

    // Load configs from JSON file here...
    std::vector<ServerConfig> configs{{"http://example.com", interval}};
    MonitoringApp app(configs, 9);
    app.Start();

    return 0;
}
```

This example doesn't include much detail on how to handle errors or retry logic since they are complex and dependent on the specific requirements of your application.

