    private readonly ExternalStorageService _storageService;
    private readonly UploadApiClient _uploadApiClient;
    private readonly MyDbContext _dbContext;

    public FileProcessingService(ExternalStorageService storageService, 
        UploadApiClient uploadApiClient, MyDbContext dbContext)
    {
        _storageService = storageService;
        _uploadApiClient = uploadApiClient;
        _dbContext = dbContext;
    }

    public async Task ProcessFileAsync(byte[] fileData, string userId)
    {
        try
        {
            var url = await _storageService.StoreToTempStorageAsync(fileData);
            BackgroundJob.Enqueue(() => UploadFileToApi(url, userId));
        }
        catch (Exception ex)
        {
            // Log the exception and rethrow it
            throw;
        }
    }

    public async Task UploadFileToApi(string url, string userId)
    {
        try
        {
            await _uploadApiClient.UploadAsync(url);
            var fileMetadata = new FileMetadataEntity { UserId = userId, Url = url };

            // Use Add instead of SaveChanges to avoid locking issues during high-concurrency scenarios
            _dbContext.FileMetadatas.Add(fileMetadata);
            await _dbContext.SaveChangesAsync();
        }
        catch (Exception ex)
        {
            // Log the exception and rethrow it
            throw;
        }
    }
}
```
