```C
#include <stdio.h>
#include <string.h>

int convert_jpeg_to_pdf(const char *input, const char *output) {
    FILE *pipe;
    int status;
    char command[1024];

    snprintf(command, sizeof(command), "convert %s -compress JPEG %s", input, output);

    pipe = popen(command, "r");

    if (pipe == NULL) {
        fprintf(stderr, "Failed to execute command: %s\n", command);
        return 1;
    }

    status = pclose(pipe);

    if (status != 0) {
        fprintf(stderr, "Command execution failed with status code %i.\n", status);
        return 1;
    }

    printf("JPEG file converted to PDF successfully!\n");

    return 0;
}
```

This function takes two arguments: the input JPEG file path and output PDF file path. It uses ImageMagick's `convert` command to convert a JPEG file to a PDF. If there is any error during execution, it prints an appropriate message to stderr and returns 1. Otherwise, it returns 0 indicating success.
