```cpp
#include <random>
#include <mutex>

class ThreadSafeRng {
public:
    using result_type = std::mt19937::result_type;

    static constexpr result_type min() { return std::mt19937::min(); }
    static constexpr result_type max() { return std::mt19937::max(); }

    ThreadSafeRng(std::random_device &rd) : gen_(rd()) {}
    ThreadSafeRng(result_type seed) : gen_(seed) {}

    result_type operator()() {
        std::lock_guard<std::mutex> lock(mutex_);
        return gen_();
    }

private:
    std::mt19937 gen_;
    std::mutex mutex_;
};
```
This code creates a thread-safe random number generator using `std::random` and `std::mutex`. It ensures that only one thread can generate the next random number at any given time, thus preventing race conditions. 

