#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <future>

// Assuming a simple structure for a geospatial point, replace it with actual one
struct GeoPoint { 
    double latitude; 
    double longitude; 
};

std::vector<GeoPoint> dataPoints; // Global data shared across threads
std::mutex mtx; // Mutex for thread safety

// Function to process a geospatial point
void processData(const GeoPoint& pt) {
    std::lock_guard<std::mutex> lock(mtx);  // Lock guard for automatic mutex management

    // Implement your logic here. This is just a dummy print operation
    std::cout << "Processing: (" << pt.latitude << ", " << pt.longitude << ")" << std::endl; 
}

// Function to add a geospatial point
void addData(const GeoPoint& pt) {
    std::lock_guard<std::mutex> lock(mtx); // Lock guard for thread safety

    dataPoints.push_back(pt); 
}

int main() {
    std::vector<std::future<void>> futures;

    // Add some sample points
    addData({10,20});
    addData({30,40});
    addData({-10,-20});

    // Launch threads for processing each point asynchronously
    for (const auto& pt : dataPoints) {
        futures.emplace_back(std::async(std::launch::async, processData, pt)); 
    }

    // Wait for all tasks to finish
    for(auto &ftr : futures) ftr.wait();

    return 0;
}
```
This is a simple example of how you can handle geospatial data processing with thread safety and asynchronous programming in C++. You would need to extend this base code to address all the other requirements such as handling different sensor types, interacting with an external RESTful API, handling network instabilities and intermittent connectivity, error handling, logging, memory usage optimization, scalability and maintainability aspects etc.
